/* chronicle data chunk: cn-10 | 战国前期 前476–前380 | 生成于 2026-09-21 */
window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-10"] = [
  { id: "cn--b476--f01", track: "cn", year: -476, yearApprox: false, dim: "figure", weight: 3, title: "赵简子卒，襄子立", summary: "赵鞅死，无恤继位，晋阳成为赵氏根本。", detail: { background: "赵鞅（简子）自晋定公以来长期执政，铸刑鼎、灭范氏中行氏之党，以赵为卿族之首。", process: "据《史记·赵世家》，简子在晋定公时为政，卒于周敬王末年，诸子中毋恤（无恤）以相人「珠玉」之试与竹简之训被立为嗣，是为襄子，居晋阳。", impact: "简子之死与襄子之立，直接决定了此后二十年间晋国卿族斗争的走向；晋阳在公元前455年被围时成为赵氏的最后根据地。", place: "晋都绛与赵邑晋阳（今山西翼城、太原西南）", figures: ["赵鞅","赵毋恤","赵伯鲁"], state: "晋国", sources: ["《史记·赵世家》","《史记·晋世家》","《史记·六国年表》"], tags: ["赵氏","卿族","晋阳"] }, related: [] },
  { id: "cn--b476--m01", track: "cn", year: -476, yearApprox: false, dim: "military", weight: 3, title: "晋伐鲜虞", summary: "晋赵氏北伐鲜虞，见于《左传》《史记》。", detail: { background: "鲜虞为白狄一支，居今河北中西部，与肥、鼓、仇犹等狄族小城相邻，屡与晋争。", process: "《左传》哀公末年与《史记·晋世家》并记周敬王四十四年晋伐鲜虞。是役由晋国卿族出兵，与范氏余党之清除、中山地区之角逐相连。", impact: "晋北界渐推至今滹沱河一带，赵氏在北地的经营为其后与中山国长期对抗张本；狄族部落联盟的离散也促成中山一国的形成。", place: "鲜虞（今河北正定、唐县一带）", figures: ["赵鞅"], state: "晋国", sources: ["《左传·哀公二十八年》（传世本纪年有异）","《史记·晋世家》","《史记·赵世家》"], tags: ["鲜虞","北狄","晋赵"] }, related: ["cn--b476--f01"] },
  { id: "cn--b476--p01", track: "cn", year: -476, yearApprox: false, dim: "politics", weight: 3, title: "周敬王崩，元王即位", summary: "敬王四十四年崩，太子仁立，是为元王。", detail: { background: "敬王在位时王室介入了王子朝之乱与吴晋争霸，靠晋国财力筑成周城，王权已依附于强国卿族。", process: "据《史记·周本纪》，敬王四十四年崩，晋伐鲜虞同年；太子仁立，是为元王（元王之名字诸书有异说）。元王在位年数，《史记》与后世纪年推算不无异同。", impact: "公元前476年前后同时被后世视为春秋与战国之分界，王室在纪年上仍为列国所共奉，实权则已降至城周之内。", place: "成周（今河南洛阳东郊）", figures: ["周敬王","周元王"], state: "东周王室", sources: ["《史记·周本纪》","《史记·六国年表》","《竹书纪年》（今本，晚出，纪年与古本有异）"], tags: ["东周","纪年","战国开端"] }, related: [] },
  { id: "cn--b475--p01", track: "cn", year: -475, yearApprox: false, dim: "politics", weight: 4, title: "《六国年表》断自元年", summary: "司马迁以周元王元年为表首，成为战国纪年之传统起点。", detail: { background: "司马迁作《六国年表》，以秦、魏、韩、赵、齐、楚及周为列，起于周元王元年（前475年），终于秦二世之亡。", process: "《史记·十二诸侯年表》《六国年表》之序自述其书起讫，谓周东迁后孔子「史记」毕见，而六国之事「秦兼有天下」，故别为表；表首称「元年」。学界对战国上限另有前476、前453、前403、前441诸说，皆以此表与《资治通鉴》为辩论焦点。", impact: "本分片即依前476年起算，与《六国年表》元年之说并行不悖；断限之异本身是先秦纪年学的核心问题。", place: "洛阳与列国", figures: ["司马迁","周元王"], state: "东周王室", sources: ["《史记·六国年表》","《史记·太史公自序》","杨宽《战国史》（上海人民出版社）"], tags: ["纪年","六国年表","断限"] }, related: ["cn--b476--p01"] },
  { id: "cn--b474--m01", track: "cn", year: -474, yearApprox: true, dim: "military", weight: 2, title: "越数伐吴，吴师疲于东方", summary: "越乘吴北会之后连年进兵，吴人日蹙。", detail: { background: "夫差北会黄池以后，吴之精卒尽在东方，越人乘虚再入，自此吴岁被越兵。", process: "《史记·越王句践世家》与《国语·越语上》所记数役之年次多不相合，《左传》绝笔以后更无编年可依，故是时越伐吴之次第全出推定，今但系其事于前474年前后。", impact: "连年之守使吴之田畴不辟、民力不散而国用日匮，为前473年姑苏之围准备了条件，也是「乘虚」与「持久」两种战略在吴越之际的第一次见效。", figures: ["越王句践","吴王夫差"], place: "吴越之境（今江苏苏州、浙江嘉兴一带）", state: "越国", sources: ["《史记·越王句践世家》","《国语·越语上》","《吴越春秋·句践外传》"], tags: ["吴越","疲敝","边兵"] }, related: ["cn--b473--m01"] },
  { id: "cn--b474--p01", track: "cn", year: -474, yearApprox: true, dim: "politics", weight: 2, title: "田常专齐政", summary: "齐简公既死，政令出于田氏，公室益卑。", detail: { background: "前481年田常（陈成子）杀齐简公与监止，立平公而相之，尽逐高氏、国氏之强族，夺其位者无所于朝。", process: "田常尽归所侵鲁、卫西鄙之田于齐以自名，又分财币以与大夫之失位者，北方之民归之；其封邑之广「与公相若」。诸书所记田氏世次与在政年数差异较大，故岁次标为推定。", impact: "田氏有齐凡数世而至太公和列于诸侯，前470年代齐国君臣名分与实权的错位已定，为战国卿族代君之案提供范式。", figures: ["田常","齐平公","监止"], place: "齐都临淄（今山东淄博临淄北）", state: "齐国", sources: ["《史记·田敬仲完世家》","《左传·哀公十四年》","《晏子春秋·内篇杂上》"], tags: ["田氏","专政","齐国"] }, related: [] },
  { id: "cn--b473--f01", track: "cn", year: -473, yearApprox: false, dim: "figure", weight: 3, title: "夫差自杀", summary: "吴王羞以面对子胥，掩面而亡。", detail: { background: "夫差杀伍子胥、北会黄池以争长，越乘虚入吴，此后连战连败，国势不复。", process: "《史记·伍子胥列传》载夫差必死乃曰「吾无以见子胥」，乃瞑面而自杀；《国语·吴语》所记辞气略异，两文皆以子胥之谶为叙事骨干。", impact: "夫差之死被后世反复书写为「拒谏亡国」的典型，伍子胥故事在吴中一带的祭祀传统与《越绝书》《吴越春秋》等晚出文献均据此铺陈。", place: "吴都姑苏（今江苏苏州）", figures: ["吴王夫差","伍子胥"], state: "吴国", sources: ["《史记·伍子胥列传》","《国语·吴语》","《越绝书》（东汉袁康、吴平辑，晚出）"], tags: ["夫差","伍子胥","吴亡"] }, related: ["cn--b473--m01"] },
  { id: "cn--b473--m01", track: "cn", year: -473, yearApprox: false, dim: "military", weight: 5, title: "越灭吴", summary: "句践久围吴都，夫差请和不许，吴亡。", detail: { background: "句践会稽之困后十年生聚，屡败吴师（黄池之役后越已杀吴太子），至是乘吴疲敝进围姑苏。", process: "据《史记·吴太伯世家》《越王句践世家》与《国语·吴语》，越军围吴都历三年，吴请为属国不许，夫差请死句践不许，乃自杀，吴遂亡。《左传》所记吴亡之年与《史记》有异，学界于前473、前478两说间互有取舍。", impact: "吴亡使长江下游首次归于一个越人政权，中原晋、齐、鲁诸国失去东南压力，句践得以北会诸侯，成为春秋末期最后一个霸主。", place: "吴都姑苏（今江苏苏州）", figures: ["越王句践","吴王夫差"], state: "越国", sources: ["《史记·吴太伯世家》","《史记·越王句践世家》","《国语·吴语》","《左传·哀公二十二年》"], tags: ["吴越","姑苏","灭国"] }, related: [] },
  { id: "cn--b472--p01", track: "cn", year: -472, yearApprox: true, dim: "politics", weight: 4, title: "句践会齐晋诸侯于徐州", summary: "越兵横行江淮河泗，诸侯毕贺，号称霸王。", detail: { background: "灭吴之后，句践渡淮北迁，与齐、晋争夺东方会盟主导权，吴故地与新附小国为其资本。", process: "《史记·越王句践世家》称当是时越「会诸侯齐鲁宋晋，号称霸王」，《竹书纪年》记「越迁于琅琊」之语，具体年份与地名（徐州、薛）诸说不一，故年代标为推定。", impact: "此次会盟标志吴越交替后东方秩序的重组，泗上诸小国此后长期在齐、鲁、越、楚之间摇摆，为战国初期外交格局之一部分。", place: "徐州（今山东滕县南一带）", figures: ["越王句践"], state: "越国", sources: ["《史记·越王句践世家》","《竹书纪年》（古本辑校）","《吴越春秋》（东汉赵晔撰，晚出）"], tags: ["会盟","霸政","琅琊"] }, related: ["cn--b473--m01"] },
  { id: "cn--b472--x01", track: "cn", year: -472, yearApprox: true, dim: "explore", weight: 4, title: "邗沟与江淮水上通道", summary: "夫差城邗、沟通江淮，为战国漕运之基础。", detail: { background: "吴为北伐齐鲁，于邗（今扬州）筑城，掘水以通江淮，又北接淮河，形成后世所谓邗沟。", process: "《左传》哀公九年记「吴城邗，沟通江淮」，《汉书·地理志》广陵郡条下亦及水路之便。其主体工程在公元前486年前后，至战国初期仍为东南诸国用兵、转漕之要道。", impact: "邗沟是中国早期人工运道中记载明确的一段，其走向奠定了此后数百江淮—中原水运网络，也是后世大运河的最早组成部分之一。", place: "邗城至末口（今江苏扬州至淮安）", figures: ["吴王夫差"], state: "吴国", sources: ["《左传·哀公九年》","《汉书·地理志下》","《中国水利史稿》（水利电力出版社）"], tags: ["运河","邗沟","交通"] }, related: [] },
  { id: "cn--b471--p01", track: "cn", year: -471, yearApprox: true, dim: "politics", weight: 3, title: "蔡迁州来，号下蔡", summary: "蔡惧吴迁近楚，既而灭于楚。", detail: { background: "蔡昭公久受吴国压制，吴亡前已请迁于楚；州来（下蔡）在淮河北岸，是楚之东北边境。", process: "《史记·管蔡世家》《左传》哀公四年以下皆载蔡之东迁，《史记·蔡世家》所记年次与《六国年表》不尽相合，故年代标为推定。", impact: "蔡、沈、许等姬姜小国自春秋末即成为吴、楚拉锯的对象，其地入楚后，楚的边界推到淮泗，与齐、晋（后为魏、宋）直接对峙。", place: "州来·下蔡（今安徽凤台）", figures: ["蔡侯齐"], state: "蔡国", sources: ["《史记·管蔡世家》","《史记·蔡世家》","《左传·哀公元年》"], tags: ["蔡国","迁都","楚国"] }, related: [] },
  { id: "cn--b470--c01", track: "cn", year: -470, yearApprox: true, dim: "culture", weight: 3, title: "《春秋》《左传》纪年之终", summary: "鲁史绝笔与《左传》末记事，界定新旧时代。", detail: { background: "《春秋》经文止于哀公十四年（前481年）「西狩获麟」，传文则延及哀公二十七年（前468年）之智伯入绛。", process: "《史记·孔子世家》谓孔子「因史记作《春秋》，始于哀公，至获麟而止」；《左传》末段所记晋国内争，正是本分片诸条之直接前史。", impact: "旧史之终与新局之始相接，后世论战国史者每自《左传》绝笔之处续述，司马迁作表亦以六国承之，战国的纪年与史学自觉皆从这一衔接处生长。", place: "鲁（今山东曲阜）", figures: ["孔子","左丘明（作者传统说法）"], state: "鲁国", sources: ["《史记·孔子世家》","《左传·哀公二十七年》","《春秋公羊传·哀公十四年》"], tags: ["春秋","史学","断限"] }, related: ["cn--b475--p01"] },
  { id: "cn--b470--p01", track: "cn", year: -470, yearApprox: true, dim: "politics", weight: 3, title: "卫出公复位之乱", summary: "辄复入为君，父子争国，卫政屡覆。", detail: { background: "蒯聩与辄父子以戚、孔氏之兵轮番据位，卫在晋国卿族干预下长期动荡。", process: "《史记·卫世家》载出公辄十二年蒯聩（庄公）袭逐辄自立，辄复奔鲁，岁余又因孔氏、元咺之党援复入；《左传》哀公末年至《竹书纪年》所记年次互有出入，故标为推定。", impact: "卫此后不复自立，见于《史记》之贬绝为小国，其乱局是孔氏、戚氏一类家臣左右君位的极端案例，也反映卿族对诸侯废立的操纵。", place: "卫都楚丘、濮阳（今河南滑县、濮阳）", figures: ["卫出公辄","卫庄公蒯聩","孔悝"], state: "卫国", sources: ["《史记·卫世家》","《左传·哀公十五年至二十六年》","《竹书纪年》（古本辑校）"], tags: ["卫国内乱","废立","卿族干预"] }, related: [] },
  { id: "cn--b469--p01", track: "cn", year: -469, yearApprox: true, dim: "politics", weight: 3, title: "宋景公卒，宋室争立", summary: "得、启与昭公迭立，六卿之族分权。", detail: { background: "宋景公头曼在位三十七年，无适子之定分，内宠与戴、武、穆诸族各拥所立。", process: "《史记·宋微子世家》载景公卒后族人攻逐所立之君，最后昭公（得）出奔、立悼公，年数与《六国年表》有异，故年代标为推定。", impact: "宋之国政自此为戴氏等宗族所把持，为后来戴氏（剔成）之变与宋国中期的权臣格局埋下伏笔。", place: "宋都商丘（今河南商丘）", figures: ["宋景公","宋昭公得","宋悼公"], state: "宋国", sources: ["《史记·宋微子世家》","《史记·六国年表》","《左传·哀公二十六年》"], tags: ["宋国","争立","宗族"] }, related: [] },
  { id: "cn--b468--p01", track: "cn", year: -468, yearApprox: true, dim: "politics", weight: 3, title: "鲁哀公出奔与卒", summary: "哀公欲借越制三桓，失败卒于在外。", detail: { background: "鲁自宣公以来三桓强而公室弱，哀公谋借越人之力去季、孟、叔孙氏。", process: "《史记·鲁周公世家》载哀公与三桓交恶，出奔卫、又之邹，卒于在外（有山氏之地），鲁人立其弟宁，是为悼公；《左传》哀公末年纪事与《史记》年次不尽合，故标为推定。", impact: "公室失国而君由大夫所立，鲁虽以礼乐旧邦自居，实际政柄已全在三桓，此后鲁在战国竞争中长期处于弱势。", place: "鲁都曲阜（今山东曲阜）", figures: ["鲁哀公","鲁悼公宁","季康子"], state: "鲁国", sources: ["《史记·鲁周公世家》","《左传·哀公二十五年至二十七年》","杨宽《战国史》（上海人民出版社）"], tags: ["三桓","公室","鲁国"] }, related: [] },
  { id: "cn--b468--x01", track: "cn", year: -468, yearApprox: true, dim: "explore", weight: 3, title: "越徙治琅琊", summary: "越由会稽北迁滨海之琅琊，转而争中原。", detail: { background: "句践灭吴后，会稽本土远离齐、鲁、宋、卫，需有北向之据点以通淮泗与海运。", process: "《吴越春秋·句践伐吴外传》《越绝书》皆载越「徙治琅琊」（在今山东胶南滨海），《竹书纪年》古本亦有越迁琅琊之文；其年与细节晚出文献互异，故年代标为推定。", impact: "此举使东南政权的力量首次长期投射到山东沿海，齐、鲁被迫面对海上一路，也促成了淮泗—河北水运与沿海航路的早期发展。", place: "琅琊（今山东胶南一带滨海）", figures: ["越王句践"], state: "越国", sources: ["《吴越春秋·句践伐吴外传》（东汉赵晔撰，晚出）","《越绝书》（晚出）","《竹书纪年》（古本辑校）"], tags: ["越","徙都","沿海航路"] }, related: ["cn--b472--p01"] },
  { id: "cn--b467--f01", track: "cn", year: -467, yearApprox: true, dim: "figure", weight: 3, title: "墨翟生年之推定", summary: "诸家据《墨子》与年世推其生于前五世纪后期。", detail: { background: "司马迁于《史记·孟子荀卿列传》仅以「或曰并孔子时，或曰在其后」出之，墨翟年代遂成聚讼。", process: "近人据《墨子·贵义》《鲁问》所记与鲁、宋、楚之君臣世系推其生年约在前479年至前460年之间，卒年约在前390年代；钱穆、冯友兰诸家所推年世互有出入。", impact: "墨子之卒世与魏文侯、楚惠王相及，故其非攻之论与止楚攻宋之事，须在魏、楚、越三力交错的战国前期格局中理解。", place: "宋、鲁之间（今河南商丘、山东曲阜一带）", figures: ["墨翟"], state: "宋国", sources: ["《史记·孟子荀卿列传》","《墨子》（孙诒让《间诂》本）","钱穆《先秦诸子系年》（商务印书馆）"], tags: ["墨家","诸子年世","生卒推定"] }, related: [] },
  { id: "cn--b466--c01", track: "cn", year: -466, yearApprox: true, dim: "culture", weight: 4, title: "卜子夏设教西河", summary: "孔子弟子言偃、商瞿之伦东西分布，子夏居西河。", detail: { background: "孔子没后，弟子散游，子夏（卜商）居卫之西河，魏文侯师事之。", process: "《史记·仲尼弟子列传》记「子夏居西河教授，为魏文侯师」，《礼记·檀弓》所记尤详；其设教之年《史记》无明文，学界多置于魏文侯初年之前后，故标为推定。", impact: "西河一系成为孔门经典向战国传受的枢纽，《诗》《春秋》《礼》之传多出其后；魏国因而先于他国取得儒学资源，与后来三晋法治之说并行。", place: "西河（今陕西东部黄河两岸或河南浚县一带，诸说不一）", figures: ["卜商","魏文侯","田子方","段干木"], state: "魏国", sources: ["《史记·仲尼弟子列传》","《史记·魏世家》","《礼记·檀弓上》"], tags: ["儒学","西河","师承"] }, related: [] },
  { id: "cn--b465--d01", track: "cn", year: -465, yearApprox: true, dim: "disaster", weight: 3, title: "战国初期水旱与饥荒", summary: "《墨子·七患》所纪凶饥之数，可推早期灾年。", detail: { background: "战国初河水、济水下游无恒堤，诸国以水为攻，凶饥与师旅相仍；《墨子·七患》历举「一谷不升谓之欠缺」以下诸名。", process: "《史记·六国年表》于各国表行中偶书灾、饥、星变，《汉书·五行志》辑先秦水旱之异，战国前期条目简少且年次多不可强定，故本条作通代推定，不敢指实某年某地。", impact: "灾荒与灌溉之利害直接催生了尽地力、平籴、引漳等政策主张，战国初的经济改革多在备荒的语境内发生。", place: "黄河中下游与淮泗流域", figures: ["墨翟"], state: "列国", sources: ["《墨子·七患》","《史记·六国年表》","《汉书·五行志》"], tags: ["灾荒","水旱","备荒"] }, related: [] },
  { id: "cn--b464--i01", track: "cn", year: -464, yearApprox: true, dim: "institution", weight: 3, title: "晋卿之县与郡", summary: "边地置郡，县设大夫，为郡县制之先驱。", detail: { background: "晋自武公并国以后，所取之地不封卿大夫而置县，赵简子誓于戚，以县、郡为赏格。", process: "《左传》哀公二年载「克敌者，上大夫受县，下大夫受郡」，晋边邑之县有大夫、有守；魏文侯时县令之任与考课已具规模，惟具体建制之年多不可指，故年代标为推定。", impact: "县、令由君主任免，与世卿采邑根本不同，是战国官僚制的起点；秦、汉之郡县即由此经由三晋之制演化而来。", place: "晋之边县（今山西、河南黄河中游两岸）", figures: ["赵鞅"], state: "晋国", sources: ["《左传·哀公二年》","《史记·秦本纪》（及《六国年表》）","《通典·职官》"], tags: ["县制","郡","官僚制"] }, related: [] },
  { id: "cn--b463--s01", track: "cn", year: -463, yearApprox: true, dim: "science", weight: 4, title: "铁农具与牛耕之推广", summary: "以铁耕见于《孟子》，出土铁器知其渐广。", detail: { background: "春秋后期铸铁已用于工具，《国语·齐语》所谓「恶金以铸锄夷斤欘」，至战国初铁器数量与种类俱增。", process: "《孟子·滕文公上》有「以铁耕乎」之问，可为当时铁耕已习见之证；近世出土之战国早期铁锄、铁铲、铁镢以湖南、河北、河南诸省为多，其年代与起源中心学界仍有争论。牛耕之名见于《史记·仲尼弟子列传》所载人名字形，推广过程无确年，故标为推定。", impact: "铁器与畜力耕作使垦田与深耕成为可能，直接支撑了晋、齐、鲁的田赋改革与魏的尽地力之教，是战国生产变革的物质基础。", place: "黄河中下游与江汉之间", figures: ["孟轲（追述）"], state: "列国", sources: ["《孟子·滕文公上》","《国语·齐语》","《史记·仲尼弟子列传》","李约瑟《中国科学技术史》（科学出版社中译本）"], tags: ["铁器","牛耕","农业技术"] }, related: [] },
  { id: "cn--b462--p01", track: "cn", year: -462, yearApprox: true, dim: "politics", weight: 3, title: "卫之再乱与悼公立", summary: "出公复辟不成，卫遂贬为小国。", detail: { background: "卫在蒯聩、辄父子反复争位之后，又因孔氏、大叔遗之党内讧，晋人屡干预其废立。", process: "《史记·卫世家》记出公去位之后，卫人更立适、悼诸君，其间有「大叔遗」之乱与晋之纳君；《六国年表》所系年与《卫世家》多不合，故年代标为推定。", impact: "卫此后不复得为独立力量，其在齐、赵之间为附庸，是战国初中等诸侯被卿族与大国外交共同侵蚀的典型。", place: "卫（今河南濮阳、滑县一带）", figures: ["卫出公辄","卫悼公"], state: "卫国", sources: ["《史记·卫世家》","《史记·六国年表》","《左传·哀公二十六年》"], tags: ["卫国","废立","附庸化"] }, related: ["cn--b470--p01"] },
  { id: "cn--b461--c01", track: "cn", year: -461, yearApprox: true, dim: "culture", weight: 3, title: "曾参之学与《礼记》传文", summary: "曾子一系之修齐之说，多存于《礼记》诸篇。", detail: { background: "曾参（子舆）为孔门后学之重，主敬身、慎终之说，弟子有乐正子春、公明仪之伦。", process: "《史记·仲尼弟子列传》称「曾参时年六十余」而卒，《大戴礼记》有《曾子立事》诸篇，《礼记》之《檀弓》《祭义》多存其门人记事；篇第成书非一时，年代标为推定。", impact: "曾子—子思—孟子一系的内省之学，是战国前期儒学最有影响的支脉，其慎独、养气之说塑造了此后儒家心性论的问题意识。", place: "鲁、卫之间（今山东武城一带）", figures: ["曾参","乐正子春"], state: "鲁国", sources: ["《史记·仲尼弟子列传》","《大戴礼记·曾子立事》","《礼记·檀弓上》"], tags: ["儒学","曾子","礼记"] }, related: ["cn--b466--c01"] },
  { id: "cn--b461--p02", track: "cn", year: -461, yearApprox: true, dim: "politics", weight: 3, title: "曾与楚之邦交", summary: "曾即随，随侯之后仍守附庸于楚之局。", detail: { background: "随国在汉东，昭王南征之所及，春秋末随救楚免楚惠王之难，故楚不并随而与之盟。", process: "《左传》定公四年、哀公元年载随释楚而吴不能得；近出曾器之铭文与《曾侯乙墓》发掘报告以曾、随为一国两名，楚与曾之世盟见于楚王熊章所作宗彝，惟列世之年多不可强定，故标为推定。", impact: "汉东姬、姜诸小国在楚北扩之后多以附庸形态存续，曾国得以保存高度发达的礼乐文化，其墓葬成为战国前期物质文化的关键标本。", place: "曾（随）（今湖北随州洛阳镇一带）", figures: ["楚惠王熊章"], state: "曾国", sources: ["《左传·定公四年》","《左传·哀公元年》","湖北省博物馆《曾侯乙墓》（文物出版社）"], tags: ["曾国","随","楚","汉东"] }, related: [] },
  { id: "cn--b460--a01", track: "cn", year: -460, yearApprox: true, dim: "art", weight: 3, title: "战国早期青铜工艺之新变", summary: "蟠螭纹、失蜡与错金银并兴，礼器趋华美。", detail: { background: "春秋中叶以后，青铜礼器自西周之庄重转向细密繁缛，诸侯卿大夫各自铸器。", process: "以出土器群比较之，战国前期之曾侯乙墓所出编钟、尊盘、鉴缶，其纹饰层叠、有透雕与错金铭文，属失蜡（熔模）与浑铸、分铸之法并用者，相关冶炼与范铸问题学界尚在讨论，年代依墓内铭文楚王熊章之器定为推定。", impact: "此类工艺水准说明战国前期的手工业组织能力已非礼制符号所能限，为后来错银、漆器与金缕之盛开了端。", place: "曾（今湖北随州）", figures: ["曾侯乙"], state: "曾国", sources: ["湖北省博物馆《曾侯乙墓》（文物出版社）","张光直《中国青铜时代》（生活·读书·新知三联书店）","《中国青铜器全集》（文物出版社）"], tags: ["青铜","失蜡法","错金银"] }, related: ["cn--b461--p02"] },
  { id: "cn--b460--i01", track: "cn", year: -460, yearApprox: true, dim: "institution", weight: 3, title: "士之游仕与客卿之始", summary: "卿族与诸侯以禄秩招士，宾萌、寄公之名并起。", detail: { background: "宗法封建下士为大夫之下层，春秋末以降士失其常职，转向以才能易禄。", process: "《战国策》诸策记布衣之士结驷连骑以干诸侯，《墨子·尚贤》主张「列德而尚贤」，魏文侯、齐威王之养士皆承此风；其起于战国初而年不可指，故标为推定。", impact: "选官由世及转为任命与考课，客卿、师傅、博士之职由此而生，士阶层成为战国政治与学术的共同承担者。", place: "三晋、齐、鲁", figures: ["魏文侯","墨翟"], state: "列国", sources: ["《战国策》（西汉刘向辑）","《墨子·尚贤上》","《史记·魏世家》"], tags: ["士阶层","养士","选官"] }, related: ["cn--b460--a01"] },
  { id: "cn--b459--m01", track: "cn", year: -459, yearApprox: true, dim: "military", weight: 3, title: "赵氏北并代", summary: "襄子因代而启北方之土，胡俗渐入三晋。", detail: { background: "简子尝以女妻代王，及简子卒而襄子立，代当赵北，为边患者久之。", process: "《史记·赵世家》记襄子因请见代王于句注之塞，使厨人操铜斗而击杀代王，遂定代；其年与前后节次诸家推排不能画一，《竹书》所记亦多亡逸，故系年出推定。", impact: "代地既入，赵之北境直与胡、翟相接，战车之利渐屈而骑射之俗渐来；后世赵武灵王之「便北边」，其地本实定于此时。", figures: ["赵毋恤","代王"], place: "代（今河北蔚县东北、山西代县一带）", state: "晋国", sources: ["《史记·赵世家》","《史记·匈奴列传》","《竹书纪年》（古本辑校）"], tags: ["赵氏","并代","北边"] }, related: ["cn--b476--f01"] },
  { id: "cn--b458--p01", track: "cn", year: -458, yearApprox: true, dim: "politics", weight: 3, title: "四卿共灭范氏、中行氏", summary: "智、赵、韩、魏尽逐晋之敌卿，分其土为邑。", detail: { background: "范氏、中行氏自定公时败奔，齐人为之城夷、百泉，余党在邯郸一带犹存，晋国遂成四卿并立之局。", process: "《史记·晋世家》《赵世家》与《六国年表》记晋出公时智伯与赵、韩、魏共攻灭范氏、中行氏，尽分其地以为邑；表与世家所系之年有前458、前456诸异，故标为推定。", impact: "敌卿之地不入公室而入四家，晋之国公已无直辖之土可言，此后二十年的卿族火并只是把四分改成三分的问题。", place: "晋之河东与邯郸（今山西西南部、河北南部）", figures: ["智伯瑶","赵襄子","韩康子","魏桓子"], state: "晋国", sources: ["《史记·晋世家》","《史记·六国年表》","《史记·赵世家》"], tags: ["晋国","卿族","范氏"] }, related: ["cn--b476--f01"] },
  { id: "cn--b457--p01", track: "cn", year: -457, yearApprox: true, dim: "politics", weight: 3, title: "智伯为政，请地韩魏", summary: "智伯以晋室名义索万家之邑，韩魏与之，赵不与。", detail: { background: "智伯（荀瑶）承智文子之后秉晋政，恃其强欲阴削三卿，乃以四夷不侵、晋室当复霸为名请地。", process: "《史记·魏世家》《韩世家》与《战国策·赵策一》载智伯请地于韩，康子与万家之邑；请于魏，桓子欲不与，赵葭（《魏世家》作「赵葭」，诸书人名小异）劝之，亦与一万家；请于赵，襄子不与，智伯遂率韩、魏之师攻赵。", impact: "以「奉晋主之命」的名义兼并非但未能成事，反而促成韩、魏倒向赵氏；此事成为法家、纵横家论「势」与「谋」的常用史例。", place: "晋都绛与智氏之地（今山西翼城、汾阳一带）", figures: ["智伯瑶","韩康子","魏桓子","赵襄子"], state: "晋国", sources: ["《史记·魏世家》","《史记·韩世家》","《战国策·赵策一》","《韩非子·十过》"], tags: ["智氏","请地","卿族斗争"] }, related: ["cn--b458--p01"] },
  { id: "cn--b456--e01", track: "cn", year: -456, yearApprox: true, dim: "economy", weight: 3, title: "邢、邯郸之冶与铸钱之家", summary: "赵之冶郭纵、魏之孔氏，皆以铁铸起于战国初。", detail: { background: "山西、河北之交故有铁山之利，邢、邯郸之民以铸为业，私家遂至与王者同富。", process: "《史记·货殖列传》追叙战国至秦之冶家，赵有郭纵、魏有孔氏、蜀有卓氏，皆以铸冶成业而富拟王侯；其世次多在战国前期至中期之间，《平准书》论山泽之利亦无年月明文，故系年出推定。", impact: "冶铸既为私家之业，则刀布之利不在公上，三晋所以须「利归于上」；后来齐之管仲官山海、秦之禁铸钱、汉之算缗，皆为此等局面所生。", figures: ["郭纵","孔氏"], place: "邢、邯郸（今河北邢台、邯郸）", state: "赵国", sources: ["《史记·货殖列传》","《史记·平准书》","《汉书·食货志下》"], tags: ["冶铁","私家","货殖"] }, related: [] },
  { id: "cn--b455--m01", track: "cn", year: -455, yearApprox: true, dim: "military", weight: 4, title: "智氏率韩魏围晋阳", summary: "晋阳被围经岁，赵人坚守以待变。", detail: { background: "赵襄子以晋阳储积素实、狱讼得中为可守，遂北走晋阳，智氏引汾水以灌之。", process: "《史记·六国年表》系晋阳之围于晋出公之世，学界有前455、前454二说；《战国策·赵策一》《韩非子·十过》《史记·赵世家》皆载围城日久、城中悬釜而炊，赵使张孟谈（诸书或单称孟谈）出说韩、魏。", impact: "晋阳之守成为中国城守史上的著名战例，也决定此后二百年的政治地理：赵氏以晋阳为根本，其北系代、南系邯郸之势由此而定。", place: "晋阳（今山西太原西南古城营一带）", figures: ["赵襄子","智伯瑶","张孟谈"], state: "晋国", sources: ["《史记·六国年表》","《史记·赵世家》","《战国策·赵策一》","《韩非子·十过》"], tags: ["晋阳","围城","赵氏"] }, related: ["cn--b476--f01"] },
  { id: "cn--b454--d01", track: "cn", year: -454, yearApprox: true, dim: "disaster", weight: 3, title: "晋水灌晋阳之城灾", summary: "决水灌城，城中沈灶产蛙，几至不支。", detail: { background: "晋水流经晋阳城西，智氏筑围堰引以灌城，非以攻城具，而以水为兵。", process: "《韩非子·十过》《吕氏春秋·义赏》《战国策·赵策一》与《史记·魏世家》皆及「晋水可以灌吾城」与「城中悬釜而炊、易子而教」一类语；文字详略互异，水攻所及之年份不可指实，故标为推定。", impact: "水攻所致的城邑之灾，使三晋对水利与堤防的利害关系极敏感，后世论河防者每以晋阳覆溺为前车之鉴。", place: "晋阳城下（今山西太原西南）", figures: ["智伯瑶","赵襄子"], state: "晋国", sources: ["《韩非子·十过》","《吕氏春秋·义赏》","《史记·魏世家》","《战国策·赵策一》"], tags: ["水攻","晋水","城灾"] }, related: ["cn--b455--m01"] },
  { id: "cn--b453--f01", track: "cn", year: -453, yearApprox: true, dim: "figure", weight: 3, title: "豫让漆身吞炭", summary: "为智伯报仇，两度刺赵襄子不成而死。", detail: { background: "豫让先事范氏、中行氏，智伯尊礼之；智伯既死，乃变名姓为刑徒入晋阳厕中挟匕首。", process: "《史记·刺客列传》《战国策·赵策一》皆载襄子两度释之，豫让乃漆身为厉、吞炭为哑，其妻不能识；后伏桥下，襄子马惊而觉，请「国士遇我，我故国士报之」之义，求击襄子之衣而拔剑三跃，伏剑死。", impact: "豫让故事是战国士以知遇相报这一伦理的极端样本，其叙事见于《战国策》而经《史记》定型，为后世游侠、门客传统的范本。", place: "晋阳（今山西太原西南）", figures: ["豫让","赵襄子"], state: "晋国", sources: ["《史记·刺客列传》","《战国策·赵策一》","《说苑·立节》"], tags: ["士","复仇","知遇"] }, related: ["cn--b453--p01"] },
  { id: "cn--b453--m02", track: "cn", year: -453, yearApprox: false, dim: "military", weight: 5, title: "三家反戈，杀智伯", summary: "张孟谈夜说韩魏，决水反灌，智氏覆灭。", detail: { background: "智伯视韩魏为可驱，方以水灌晋阳而得意，韩魏则以自身封邑亦在水攻之列，遂生异志。", process: "《史记·魏世家》《韩世家》《赵世家》《史记·六国年表》与《战国策·赵策一》皆载张孟谈夜出见韩、魏之君，约定反戈；赵氏杀守堤之卒，反决水以灌智氏军，军败，就杀智伯，尽并其众。", impact: "此役与秦之统一、三家分晋同为《资治通鉴》《六国年表》所取的时代节点，晋国政权自此名存，战国七雄格局开始成形。", place: "晋阳城下（今山西太原西南）", figures: ["赵襄子","张孟谈","魏桓子","韩康子"], state: "晋国", sources: ["《史记·魏世家》","《史记·赵世家》","《史记·六国年表》","《战国策·赵策一》","《资治通鉴》卷一"], tags: ["晋阳","三家灭智","战国开局"] }, related: ["cn--b455--m01", "cn--b453--p01"] },
  { id: "cn--b453--p01", track: "cn", year: -453, yearApprox: false, dim: "politics", weight: 4, title: "三家分智氏之地", summary: "智宗覆亡，其地三分，晋政归韩赵魏。", detail: { background: "智伯之亡并及族人，《国语·晋语九》载智果早见智氏必败，改姓为辅氏，其宗得全。", process: "《史记·周本纪》《晋世家》与《六国年表》记三家分智氏之邑，晋哀公、幽公以下不复自专；赵襄子漆智伯之头以为饮器，其怨毒之深，见于《史记·刺客列传》所叙豫让之语。", impact: "自灭智之后，晋之存国只余名号，至前403年周威烈王册命三晋为诸侯，实为对这一定局的事后追认。", place: "晋之河东（今山西西南部）", figures: ["赵襄子","智果"], state: "晋国", sources: ["《史记·晋世家》","《史记·刺客列传》","《史记·六国年表》","《国语·晋语九》"], tags: ["三家分晋","智氏","晋室"] }, related: ["cn--b453--m02"] },
  { id: "cn--b452--s01", track: "cn", year: -452, yearApprox: true, dim: "science", weight: 3, title: "战国初期之城防与守御技术", summary: "墨家诸篇所记城守之制，可窥当时工防水平。", detail: { background: "晋阳的围守与用水攻之例，说明当时攻城技术已不限于临冲，围堰、地道、云梯并用。", process: "《墨子》自《备城门》以下十一篇记城门、敌台、行炉、转射机、连弩之车及守城人员之编制，多认为出墨者后学所述而反映战国早期之制，成书年世无定，故年代标为推定。", impact: "这些记载是中国现存最早的城防工程文献，也是攻城与守城相互推动的军事技术史的起点之一。", place: "三晋与宋、鲁之间", figures: ["墨翟（学派）"], state: "列国", sources: ["《墨子·备城门》以下诸篇（孙诒让《间诂》本）","《司马法》（《武经七书》本）","湖北省博物馆《曾侯乙墓》（文物出版社）"], tags: ["城防","墨家","军事工程"] }, related: ["cn--b450--s02"] },
  { id: "cn--b451--e01", track: "cn", year: -451, yearApprox: true, dim: "economy", weight: 3, title: "井田疆界之坏与税制之变", summary: "采邑拆解、田租改征，旧疆亩渐不可守。", detail: { background: "春秋末各国已税亩、用田赋，战国初卿族分邑，田之授受与赋之科敛俱非旧制。", process: "《汉书·食货志》上叙「至战国，兼并不止」而王制大坏，《孟子·滕文公上》以「夫仁政必自疆界始」刺时之慢于正地，皆就战国前期田制之紊乱立论；其变化为非一事一年，故标为推定。", impact: "田制的松动既造成农民失地的隐患，也为按户、按亩征赋与「尽地力之教」一类政策开了路，是战国赋税国家的起点。", place: "三晋与齐、鲁", figures: ["孟轲（追述）"], state: "列国", sources: ["《汉书·食货志上》","《孟子·滕文公上》","杨宽《战国史》（上海人民出版社）"], tags: ["田制","赋税","井田"] }, related: [] },
  { id: "cn--b451--m01", track: "cn", year: -451, yearApprox: true, dim: "military", weight: 3, title: "秦与晋魏之河西争夺", summary: "魏东侵河西，秦屡失地，为吴起守西河之背景。", detail: { background: "自春秋末晋人逾河筑城，秦之东境渐蹙；魏氏既强，遂专力西向，取河西之地。", process: "《史记·秦本纪》于躁公、怀公之世屡书「与晋（魏）战」及「筑」某城，《六国年表》魏表所系尤多；然秦之纪事与魏表年月互有出入，其确年学界未能画一，故本条作通段推定。", impact: "河西之失使秦国长期被摈于崤、河以西，至献公、孝公之际乃谋收复；魏则因西河之地而有吴起之治与强兵。", place: "河西（今陕西东部黄河西岸）", figures: ["秦躁公","魏文侯"], state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·魏世家》"], tags: ["河西","秦魏","边疆"] }, related: [] },
  { id: "cn--b450--c01", track: "cn", year: -450, yearApprox: true, dim: "culture", weight: 4, title: "墨子立兼爱非攻之说", summary: "以兼相爱、交相利攻礼制之别，非攻诛不义之战。", detail: { background: "墨翟学儒者之业、受孔子之术，以为其礼烦扰而不说，遂别立其教。", process: "《墨子》之《兼爱》《非攻》《尚贤》《节用》诸篇为其本旨所在，《韩非子·显学》谓子墨子之后分为三，「墨离为三，取舍相反不同，而皆自谓真墨」；其说之立非一年之事，故标为推定。", impact: "墨家在战国前期与儒并为显学，其非攻之论与守城之技，使小国有以拒大国之攻，也引发儒家与名者的一系列反驳。", place: "宋、鲁之间", figures: ["墨翟"], state: "宋国", sources: ["《墨子·兼爱上》","《墨子·非攻上》","《韩非子·显学》","《史记·孟子荀卿列传》"], tags: ["墨家","兼爱","非攻"] }, related: ["cn--b467--f01"] },
  { id: "cn--b450--s02", track: "cn", year: -450, yearApprox: true, dim: "science", weight: 3, title: "墨家之光学、力学与机关", summary: "《墨经》记影、镜、杠杆与城防器械之论。", detail: { background: "墨者以工巧闻名，《公输》《备梯》诸篇皆及其器械制作，《墨经》则记其析理之精。", process: "《墨子·经下》《经说下》有景不徙、小孔成像（「景到，在午有端」）、镜之鉴形，及权衡轻重之杠杆之论；文字多错简，读法自孙诒让以降诸家互异，其年亦无从指实，故标为推定。", impact: "这些条目是中国最早见于成文史料的几何光学与力学讨论，其传统在秦汉之际为名者所继。", place: "宋、鲁之间", figures: ["墨翟（学派）"], state: "宋国", sources: ["《墨子·经下》《经说下》（孙诒让《间诂》本）","李约瑟《中国科学技术史》（科学出版社中译本）"], tags: ["墨经","光学","力学"] }, related: ["cn--b452--s01"] },
  { id: "cn--b449--c01", track: "cn", year: -449, yearApprox: true, dim: "culture", weight: 3, title: "杨朱之说的流行", summary: "与墨兼相对，为我之说盛于当世。", detail: { background: "战国初处士横议，杨朱不著书而其说以口耳相传，孟子斥其与墨氏并为天下之两大。", process: "《孟子·尽心上》称「杨子取为我，拔一毛而利天下，不为也」，《滕文公下》称「天下之言，不归杨则归墨」；今本《列子·杨朱》篇晚出，其思想与杨朱本说的关系学界有争议，故本条年代标为推定。", impact: "为我、贵生之说反映了士脱离宗族后的自保立场，孟子的辟杨墨与后来道家养生论之兴，都以此为对话对象。", place: "宋、鲁、卫之间", figures: ["杨朱","孟轲（追述）"], state: "列国", sources: ["《孟子·尽心上》","《孟子·滕文公下》","《列子·杨朱》（晚出，真伪有争议）"], tags: ["杨朱","贵己","显学"] }, related: ["cn--b450--c01"] },
  { id: "cn--b448--f01", track: "cn", year: -448, yearApprox: true, dim: "figure", weight: 3, title: "公输般之巧", summary: "云梯之械与木鹊之削，见当时工巧之极。", detail: { background: "公输般（鲁班）为鲁人而仕楚，为楚造强弓、云梯与舟战之钩拒，是战国初匠人的代表。", process: "《墨子·公输》记「公输盘为楚造云梯之械，成，将以攻宋」，《墨子·鲁问》又记其削竹木为鹊「成而飞之，三日不下」而墨子以为不如匠之为车辖；《孟子·离娄上》「公输子之巧」亦为其时熟语。其与墨子相见之年诸家推定互异，故标为推定。", impact: "公输般其人其事成为后世工匠之祖的传说核心，也说明战国初器械之巧已能与攻守之策直接相关。", place: "鲁、楚之间", figures: ["公输般","墨翟"], state: "楚国", sources: ["《墨子·公输》","《墨子·鲁问》","《孟子·离娄上》"], tags: ["工匠","云梯","墨子"] }, related: ["cn--b450--c01"] },
  { id: "cn--b447--p01", track: "cn", year: -447, yearApprox: false, dim: "politics", weight: 3, title: "楚灭蔡", summary: "惠王北扩，下蔡之蔡遂绝。", detail: { background: "蔡自昭公以来屡为吴、楚所陵，迁州来之后地当吴会上游，去楚益近而危益甚。", process: "《史记·管蔡世家》《蔡世家》记楚惠王灭蔡侯齐而迁其民，《左传》哀公以后之记事与《史记》年次有异，《六国年表》楚表所系在惠王之世，诸家定为前447年。", impact: "蔡亡使楚的东北界直抵淮南、淮北，泗上诸小国自此失一屏障，吴越旧地的北出之路亦为楚所扼。", place: "下蔡（今安徽凤台）", figures: ["楚惠王熊章","蔡侯齐"], state: "楚国", sources: ["《史记·管蔡世家》","《史记·六国年表》","《左传·哀公元年》"], tags: ["楚国","灭国","淮域"] }, related: ["cn--b471--p01"] },
  { id: "cn--b446--i01", track: "cn", year: -446, yearApprox: true, dim: "institution", weight: 4, title: "上计之制行于魏", summary: "郡县吏岁集计簿，君亲课其殿最。", detail: { background: "卿族分邑之后，邑之宰、令由君主任免，须有可核之课，计簿之制因而确立。", process: "《韩诗外传》记子质为魏大夫有罪出关之语，《史记·滑稽列传》褚少孙补文记魏文侯时邺令岁上计、收上书言者之奏，皆可窥上计之程序；战国初之制与《二年律令》《效律》一类秦简所记者有沿革关系，其初年不可指实，故标为推定。", impact: "上计使国君能以数字监督地方，是战国官僚制度与国君集权的技术枢纽，秦汉之集计、课殿最皆承此而来。", place: "魏（今山西西南部、河南北部）", figures: ["魏文侯","西门豹"], state: "魏国", sources: ["《史记·滑稽列传》（褚少孙补）","《韩诗外传》","杨宽《战国史》（上海人民出版社）"], tags: ["上计","考课","官僚制"] }, related: ["cn--b464--i01"] },
  { id: "cn--b445--f01", track: "cn", year: -445, yearApprox: true, dim: "figure", weight: 3, title: "魏文侯式段干木之闾", summary: "过贤人之间而伏轼，秦人议魏之不可伐。", detail: { background: "段干木受业子夏之门人，守义不臣诸侯，居魏而不在位，为文侯所敬。", process: "《史记·魏世家》与《吕氏春秋·期贤》皆记文侯过段干木之闾而式，御者谏之，文侯以「木贤者也」答之；《期贤》并载秦人以此议魏国未可加兵之说，其事之年世不可指实，故标为推定。", impact: "此事为战国礼贤传统的样板，士之清议自此成为君主须计量的政治资本，与魏文侯一时之人才聚集互为表里。", place: "魏（今山西夏县、河南陕县之间河济之地）", figures: ["魏文侯斯","段干木"], state: "魏国", sources: ["《史记·魏世家》","《吕氏春秋·期贤》","《汉书·艺文志》"], tags: ["礼贤","士","魏文侯"] }, related: ["cn--b460--i01"] },
  { id: "cn--b445--p01", track: "cn", year: -445, yearApprox: false, dim: "politics", weight: 4, title: "魏文侯斯即位", summary: "魏斯立，礼贤任能，魏遂为三晋之首。", detail: { background: "魏自桓子以来与赵、韩共灭智氏，及其世而地分河曲、河内，须有内治之方以抗齐、楚、秦。", process: "《史记·魏世家》《六国年表》于文侯改元与卜子夏、田子方、段干木之交游皆在其即位前后，旧说多定于前445年；《竹书纪年》所载魏世纪年与《史记》有异，故文侯初年之细节学界未有一致说法。", impact: "魏文侯一朝兼用儒、法、兵、政之士，李悝之法、吴起之兵、西门豹之政皆成于此，魏遂为战国首强。", place: "魏都安邑（今山西夏县西北禹王城）", figures: ["魏文侯斯","卜商","田子方","段干木"], state: "魏国", sources: ["《史记·魏世家》","《史记·六国年表》","《资治通鉴》卷二"], tags: ["魏文侯","礼贤","变法"] }, related: ["cn--b466--c01"] },
  { id: "cn--b445--p02", track: "cn", year: -445, yearApprox: true, dim: "politics", weight: 3, title: "楚灭杞", summary: "东迁之杞为楚所并，其年史文阙而莫审。", detail: { background: "杞东迁淳于、迁于负夏之属，介于陈、楚之间，国小祀微。", process: "《史记·陈杞世家》于杞之末世自谓「其后世弥益远」，明言「或曰至楚简王而后灭杞」；通史多系楚灭杞于前445年前后，与《史记》二说相去颇远，故本条年代标为推定。", impact: "夏后之裔至此不国，楚尽有泗上之地，齐、鲁的南界直接暴露于楚，泗上小国的存亡自此系于大国之和战。", place: "杞（今山东安丘、诸城一带）", figures: ["楚惠王熊章"], state: "楚国", sources: ["《史记·陈杞世家》","《史记·楚世家》","杨宽《战国史》（上海人民出版社）"], tags: ["杞国","楚国","小国存灭"] }, related: ["cn--b447--p01"] },
  { id: "cn--b444--s01", track: "cn", year: -444, yearApprox: true, dim: "science", weight: 4, title: "甘德、石申之星占历数", summary: "赵有甘公、魏有石申，星经之名自此而立。", detail: { background: "春秋世官之史在战国转为私家之学，天文历数由王官散于列国。", process: "《史记·天官书》历举战国知天算者，以赵有甘公、魏有石申与齐、楚之太史并列；《晋书·天文志》叙甘、石二家之《星经》，《隋书·经籍志》著录甘氏、石氏之书而今存本皆出后人重辑，其原书之年世不可强定，故标为推定。", impact: "甘、石所记恒星之位与五星之行，是先秦天文观测最系统的成果；后世历法与星表多所取资，与曾、楚诸国出土数术竹简互为印证。", place: "魏、赵（今山西、河南黄河中游两岸）", figures: ["甘德","石申"], state: "魏国", sources: ["《史记·天官书》","《晋书·天文志上》","《隋书·经籍志》"], tags: ["天文","星经","历数"] }, related: ["cn--b445--p01"] },
  { id: "cn--b443--e01", track: "cn", year: -443, yearApprox: true, dim: "economy", weight: 3, title: "布币、刀币之区域流通", summary: "三晋用布，齐燕用刀，楚用铜贝与金版。", detail: { background: "商业与军赋日重，原有之物物交换与称金不足以应小额交易，铸币因地区习惯而兴。", process: "考古所见空首布、平首布流行于三晋与周、郑，齐之刀币与燕之明刀行于东方，楚之铜贝、郢爰行于江淮；《汉书·食货志》下追述钱货之源流，其分别定型之年不可指实，故标为推定。", impact: "货币之区域化既便利了战国初的交换与赋敛，也使各国得以自权其轻重，成为后来秦统一钱制的历史前提。", place: "三晋、齐燕、荆楚", figures: ["白圭（追述）"], state: "列国", sources: ["《汉书·食货志下》","《史记·平准书》","《史记·货殖列传》","《钦定钱录》（清乾隆内府刻本）"], tags: ["货币","布币","刀币"] }, related: [] },
  { id: "cn--b442--c01", track: "cn", year: -442, yearApprox: true, dim: "culture", weight: 3, title: "子思之学与《中庸》之传", summary: "孔孙伋承曾门，慎独、时中之说出焉。", detail: { background: "孔伋（子思）为孔子之孙，受业于曾参之门，居鲁宋之间，诸侯礼之而不能大用。", process: "《史记·孔子世家》谓「子思作《中庸》」，《孔丛子》所记子思言行多出后世傅会，《礼记》之《中庸》《表记》《坊记》《缁衣》诸篇与子思一系之关系至今聚讼，故年代与作者皆标为推定。", impact: "由曾子至子思至孟子之心性一脉，是战国儒学最有系统的一支，《中庸》之慎独、诚、时中诸论遂为宋以后儒学之骨干。", place: "鲁、宋之间（今山东曲阜、河南商丘）", figures: ["孔伋","曾参","孟轲（受业其门人）"], state: "鲁国", sources: ["《史记·孔子世家》","《礼记·中庸》","《孟子·离娄下》"], tags: ["子思","中庸","儒学"] }, related: ["cn--b461--c01"] },
  { id: "cn--b441--p03", track: "cn", year: -441, yearApprox: true, dim: "politics", weight: 3, title: "周室诸子争立", summary: "贞定王崩，哀王、思王相杀，考王以立。", detail: { background: "王室地蹙众寡，而诸子犹因晋国之党与而争位，君嗣之定常待外力。", process: "《史记·周本纪》载贞定王崩后太子去疾立为哀王，其弟思王与韩、赵之兵攻杀哀王，考王又攻杀思王而自立；《六国年表》与《周本纪》纪年不合，古本《竹书》所记又异，故标为推定。", impact: "三年之内王位三易而皆由晋卿成之，周室之存续已全在三晋的意旨之中，为十二年后册命三晋作了反面的铺垫。", place: "成周、王城（今河南洛阳）", figures: ["周贞定王","周哀王","周考王"], state: "东周王室", sources: ["《史记·周本纪》","《史记·六国年表》","《竹书纪年》（古本辑校）"], tags: ["王室内乱","晋卿","东周"] }, related: ["cn--b476--p01"] },
  { id: "cn--b440--p04", track: "cn", year: -440, yearApprox: true, dim: "politics", weight: 4, title: "西周惠公别封于河南", summary: "考王封弟揭于河南，周分东、西二公。", detail: { background: "王畿本狭，考王既立，欲安其母弟而无可封之地，乃即王城之河南而别为一国。", process: "《史记·周本纪》「考王封其弟揭于河南，是为西周惠公，以承周职」，《汉书·地理志》弘农郡河南县下班固自注亦及西周、东周之分；其封年《史记》无明文，旧说定于考王时（约前440年），学者或系之于周显王时，故标为推定。", impact: "自是而后周有西周、东周两君，王世益乱，其地至秦庄襄王元年始入于秦；此事是先秦封国解体在王畿内部的最后回响。", place: "河南（王城，今河南洛阳西）", figures: ["周考王","西周惠公揭"], state: "东周王室", sources: ["《史记·周本纪》","《汉书·地理志上》","《史记·秦本纪》"], tags: ["西周惠公","王畿","分封"] }, related: ["cn--b441--p03"] },
  { id: "cn--b440--x01", track: "cn", year: -440, yearApprox: true, dim: "explore", weight: 4, title: "《禹贡》九州的地理构想", summary: "以九区分山水贡赋，成战国人之地理想象。", detail: { background: "列国疆理既广，九州之旧说与水利、贡赋之实际须有综合之叙述。", process: "《尚书·禹贡》分冀、兖、青、徐、扬、荆、豫、梁、雍九州，系以导山导水、上中下三错之赋与五服之制；其成书年代自近代考订者以来有西周、春秋末、战国初、战国中、秦统一前后诸说，本条从通行之战国前期说而标为推定。", impact: "《禹贡》把分裂的政治现实编入一个统一地理框架之中，后世之郡县区划、河患议论与统一观念多引为据，是中国早期地理文献中影响最深的一部。", place: "三晋与齐鲁之间（成书地无定说）", figures: ["顾颉刚（近代考订者）"], state: "列国", sources: ["《尚书·禹贡》","顾颉刚《（禹贡）注释研究》（中华书局）","《史记·河渠书》"], tags: ["禹贡","九州","地理"] }, related: [] },
  { id: "cn--b439--e01", track: "cn", year: -439, yearApprox: true, dim: "economy", weight: 2, title: "魏之河东盐利", summary: "安邑之盬与池盐之饶，为魏国富厚之本。", detail: { background: "河东安邑之西有盐池，天然之盬不待煮而成，其利自春秋以来为晋人所守。", process: "魏都安邑正当池盐之旁，河东之盐行于赵、卫、宋、郑之间；文侯之世西门豹守邺而河内之饶益著。官营与税法之细史无明文，诸家所估差异较大，故系年出推定。", impact: "盐利为「尽地力」之外的国家收入，使三晋得以久用兵于秦齐楚之际；秦后来之围安平、夺河东，亦为此地。", figures: ["魏文侯","西门豹"], place: "河东安邑与盐池（今山西运城、夏县一带）", state: "魏国", sources: ["《说文解字》「盬」字下条","《史记·孙子吴起列传》","《汉书·地理志上》河东郡条"], tags: ["盐利","安邑","河东"] }, related: [] },
  { id: "cn--b439--f01", track: "cn", year: -439, yearApprox: true, dim: "figure", weight: 3, title: "卜子夏之卒", summary: "孔门文学之高弟，西河一系之宗师。", detail: { background: "卜商（子夏）卫温国人，少于孔子四十四岁，孔子没后居西河教授，魏文侯师之。", process: "《史记·仲尼弟子列传》载其言行而不记卒年，其生卒据《孔子家语·七十二弟子解》与后世辑考推为前507年前后至前440年代之间；《礼记·檀弓上》记其丧子哭而失明之事，可为其晚年在卫之证，故年代标为推定。", impact: "子夏之门有田子方、段干木、公羊高、谷梁赤之属（传说成分较多），其西河之教为儒学向三晋传播的枢纽。", place: "卫之西河（今河南浚县、内黄一带，或说在陕西东部）", figures: ["卜商","魏文侯"], state: "卫国", sources: ["《史记·仲尼弟子列传》","《孔子家语·七十二弟子解》","《礼记·檀弓上》","《孔子集语》（宋薛据辑）"], tags: ["子夏","西河","儒学"] }, related: ["cn--b466--c01"] },
  { id: "cn--b438--x01", track: "cn", year: -438, yearApprox: true, dim: "explore", weight: 2, title: "太行井陉之道", summary: "太行诸陉渐通，上党与河北往来有常道。", detail: { background: "太行一线东西绝壁，惟数陉可通车骑，井陉、邢台之属当其要者。", process: "三晋之有上党、赵之保晋阳、中山之隔燕赵，皆缘此诸陉。「井陉」之名后见于韩信伐赵之役，其道至迟战国早期已为行旅与兵争所用；开通年月与道里皆出追记，故系年推定。", impact: "山道既通，河内河东与冀州之间得以用大众，中山之所以能阻山为固、魏之所以须假道而攻，并由此局面而生。", figures: ["赵毋恤"], place: "井陉至上党（今河北井陉、山西长治一带）", state: "晋国", sources: ["《史记·赵世家》","《史记·淮阴侯列传》","《太行山记》（北魏崔浩撰，晚出追叙）"], tags: ["太行","山道","上党"] }, related: [] },
  { id: "cn--b437--a01", track: "cn", year: -437, yearApprox: true, dim: "art", weight: 2, title: "欧冶、干将之冶剑", summary: "吴越之冶工名于楚廷，名剑之说由此而广。", detail: { background: "吴越之世已以剑名，龙渊、太阿、湛卢、鱼肠、盘郢之属，并传为欧冶子、干将所作。", process: "《越绝书·外记宝剑》记楚王使风胡子干将、欧冶子作剑三枚，又薛烛鉴剑之说；其书出东汉，事多属传说，剑之年代不可信，今但用以见五世纪中叶吴越之冶工已为名于楚廷。现存越王之剑属铭文可以相证。", impact: "兵刃见贵，楚得其工而诸侯以利器相尚，器之善与士之众并重，为战国军备竞争之一端；干将故事后来成为侠与工巧之题材。", figures: ["欧冶子","干将","楚惠王"], place: "楚之鄂与吴越故地（今湖北大冶、江苏苏州一带）", state: "楚国", sources: ["《越绝书·外记宝剑》（东汉辑，晚出传说）","《吴越春秋·阖闾内传》","《战国策·赵策一》"], tags: ["冶剑","名器","工巧"] }, related: [] },
  { id: "cn--b437--c01", track: "cn", year: -437, yearApprox: true, dim: "culture", weight: 3, title: "法术之言兴于三晋", summary: "晋人主「以法治国」，为法家立论之前驱。", detail: { background: "晋国自铸刑鼎、县制以来，卿族之治以法度、课计为务，异于齐鲁之礼治。", process: "《韩非子·心度》以「法与世转变」为论，《二柄》以刑德为君之具，皆本于三晋之政；《慎子》贵势、《申子》主术，其学皆起于晋与韩、魏。前期之文多亡，其说只能由晚出之书与《史记》诸传追溯，故标为推定。", impact: "三晋为法家之故乡，李悝、吴起、商鞅、申不害一线相承；这一传统与本分片所记之县制、上计、武卒诸条互为表里。", place: "三晋（今山西、河南黄河中游两岸）", figures: ["李悝","慎到（后学）","韩非（追述）"], state: "魏国", sources: ["《韩非子·心度》","《韩非子·二柄》","《史记·老子韩非列传》"], tags: ["法家","法术","三晋"] }, related: ["cn--b464--i01"] },
  { id: "cn--b436--c01", track: "cn", year: -436, yearApprox: true, dim: "culture", weight: 2, title: "刑名法术之渐", summary: "循名责实之术，出晋郑之刑书而成于三晋。", detail: { background: "郑有邓析之辩，晋有铸刑鼎之事，名实形名之说至三晋而为治国之具。", process: "李悝在魏以《法经》为治，后学有申不害之徒以名家相韩；《韩非子》所记李悝「食有劳而禄有功」之语，与循名责实之指相通。其间师承与年月多不可考，各方记载差异较大，故系年推定。", impact: "名法之学出于理民之急而非出于辩者之口，三晋之法与术并行，为后来商鞅之徒入秦立制所自出。", figures: ["李悝","申不害","韩非"], place: "三晋之境（今山西、河南中部）", state: "魏国", sources: ["《韩非子·显学》","《韩非子·问田》","《史记·老子韩非列传》"], tags: ["名法","循名责实","三晋"] }, related: [] },
  { id: "cn--b436--f01", track: "cn", year: -436, yearApprox: true, dim: "figure", weight: 3, title: "曾参之死", summary: "「启手足」之语定儒门修身之极则。", detail: { background: "曾参事亲至孝，主「战战兢兢，如临深渊」之省身功夫，弟子守其寝门而记其终。", process: "《史记·仲尼弟子列传》载其孝亲与「曾参杀人」之疑，《礼记·檀弓上》记其病革易箦之事，《论语·泰伯》记其将终召门弟子曰「而今而后，吾知免夫」；其卒年据《弟子列传》所记年六十六上推约在前436年前后，故标为推定。", impact: "曾子一系的慎独、养气与孝治之说，经其弟子及门人之手传入子思、孟轲，构成战国儒学的主干之一。", place: "鲁（今山东武城、曲阜一带）", figures: ["曾参","乐正子春","孟轲（后学）"], state: "鲁国", sources: ["《史记·仲尼弟子列传》","《礼记·檀弓上》","《论语·泰伯》","《孟子·离娄上》"], tags: ["曾子","修身","儒学"] }, related: ["cn--b461--c01"] },
  { id: "cn--b435--f01", track: "cn", year: -435, yearApprox: true, dim: "figure", weight: 3, title: "曾参卒于鲁", summary: "临终启手足，孝道之传自鲁及于南北。", detail: { background: "曾参少孔子四十六岁，以孝闻，传统以为《孝经》之问者与《大学》之所出。", process: "《礼记·檀弓上》记其病且死，召门人而启手足，曰「战战兢兢，如临深渊，如履薄冰」，乃曰「而今而后，吾知免夫」；其卒年据诸家推排在前436至前430之间，不得而书，故标推定。", impact: "曾子之传南及子思、北入西河，吴起尝学于曾氏，其「士不可以不弘毅」诸语成为后世儒者修身之据。", figures: ["曾参","曾元","乐正箴"], place: "鲁（今山东嘉祥、费县一带）", state: "鲁国", sources: ["《礼记·檀弓上》","《史记·仲尼弟子列传》","《孟子·离娄下》"], tags: ["曾子","孝道","儒学"] }, related: [] },
  { id: "cn--b434--d01", track: "cn", year: -434, yearApprox: true, dim: "disaster", weight: 2, title: "河济堤防之作", summary: "两岸筑堤，以邻国为壑，水患自是渐重。", detail: { background: "古之治水以疏，至战国各以疆界为壅，缘河缘济之民遂以堤为守。", process: "《汉书·沟洫志》载贾让之议追言堤防之作起于战国，距河数里之堤各为其国；《孟子》讥以邻国为壑，正指壅防之害。始作之年月不可考，今约系于五世纪中叶。", impact: "堤成而河有定槽，田得以久居，然一决则并数国邑落漂没，水旱之灾由是常与兵争相乘，引漳、灌城诸役皆缘此而生。", figures: ["贾让","孟轲"], place: "河内、河东之河岸（今山西、河南黄河两岸）", state: "魏国", sources: ["《汉书·沟洫志》","《孟子·告子下》","《管子·度地》（追记水官之制）"], tags: ["堤防","河患","水灾"] }, related: [] },
  { id: "cn--b433--a01", track: "cn", year: -433, yearApprox: false, dim: "art", weight: 4, title: "曾侯乙编钟", summary: "六十五枚一钟双音，先秦乐制之大成。", detail: { background: "1978年湖北随县（今随州）擂鼓墩一号墓出土，墓主为曾（随）国之君乙，钟架分三层八组悬于曲形铜架上。", process: "曾侯乙编钟通称六十五枚，钟体多铸乐律铭文，与楚、周、晋诸国之律名相为释；其年代据楚王熊章所作宗彝之纪年铭文推为楚惠王五十六年，即前433年（铭文个别字的释读诸家尚有异说，见所附报告与汇编）。", impact: "这套器物使后世第一次见到战国前期完整的乐悬制度与音律术语，改写了先秦音乐史，也证明汉东小国在楚之庇护下的文化高度。", place: "曾（今湖北随州洛阳镇擂鼓墩）", figures: ["曾侯乙","楚惠王熊章"], state: "曾国", sources: ["湖北省博物馆《曾侯乙墓》（文物出版社）","《曾侯乙钟磬铭文乐学资料汇编》（中华书局）"], tags: ["编钟","乐悬","曾国"] }, related: ["cn--b461--p02"] },
  { id: "cn--b433--f02", track: "cn", year: -433, yearApprox: true, dim: "figure", weight: 3, title: "曾侯乙之世", summary: "名乙之曾君，与楚惠王世修好。", detail: { background: "曾（随）为汉东姬姓小国，世附于楚，其君之世系《史记》不载，多赖出土铜器以补。", process: "曾侯乙之器见于擂鼓墩一号墓所出钟、鼎、簋诸器之铭文，楚王熊章为其作宗彝，墓之年代由是得定；其即位与卒之纪年因曾国之史阙如，学界推定略有出入，故标为推定。", impact: "曾侯乙一墓所载之器、简、乐、礼，成为今天重建战国前期南方列国物质文化与邦交关系的第一手凭据。", place: "曾（今湖北随州）", figures: ["曾侯乙","楚惠王熊章"], state: "曾国", sources: ["湖北省博物馆《曾侯乙墓》（文物出版社）","《殷周金文集成》（中华书局）"], tags: ["曾国","金文","附庸"] }, related: ["cn--b461--p02"] },
  { id: "cn--b433--s01", track: "cn", year: -433, yearApprox: false, dim: "science", weight: 4, title: "编钟铭文之律数与合金", summary: "一钟二音与十二律之具，见乐律与冶金之合。", detail: { background: "青铜乐钟之制，自西周之爵列至此已能一钟发二音，其音高差与钟体之长短、壁厚相关。", process: "曾侯乙钟之正鼓音与侧鼓音常作小三度关系，铭文以律名、阶名与楚、周、晋之异名相应；合金成分之测定与「金有六齐」之说可相印证（《周礼·考工记》「六齐」条为其类书证），惟《考工记》之年代与国属学界仍有争论。", impact: "这批数据把先秦的音律学从文献之争变为可测之器，是战国前期科学知识与礼乐工艺相合之最有力的一例。", place: "曾（今湖北随州）", figures: ["曾侯乙"], state: "曾国", sources: ["湖北省博物馆《曾侯乙墓》（文物出版社）","《周礼·考工记》","李约瑟《中国科学技术史》（科学出版社中译本）"], tags: ["乐律","青铜合金","考工记"] }, related: ["cn--b433--a01"] },
  { id: "cn--b432--m01", track: "cn", year: -432, yearApprox: true, dim: "military", weight: 3, title: "楚灭莒", summary: "东夷之大者亡于楚，淮泗之上无与抗。", detail: { background: "莒为东夷大国，介于齐鲁楚越之间，春秋末屡与鲁争而自保于齐。", process: "楚简王之世灭莒，墨子所称「荆之声王」以前之大事；其年在简王元年或后数年，诸书所记与齐鲁之年次不能相合，各方记载差异较大，故标推定。", impact: "莒亡则楚东境直与泗上相值，齐之南鄙始有楚患，鲁自是南北皆逼于大国，而越之北疆亦与楚接。", figures: ["楚简王","莒渠丘公"], place: "莒（今山东莒县）", state: "楚国", sources: ["《墨子·非攻中》","《史记·楚世家》","《史记·齐太公世家》"], tags: ["莒国","灭国","东夷"] }, related: ["cn--b432--p01"] },
  { id: "cn--b432--p01", track: "cn", year: -432, yearApprox: true, dim: "politics", weight: 3, title: "楚惠王卒，简王立", summary: "在位最久之楚君死，楚东扩之业既定。", detail: { background: "惠王自吴人入郢之后即位，北并陈、蔡、杞，东拒吴越，为楚复强之世。", process: "《史记·楚世家》记惠王在位五十七年（或作六十四年，诸家校订不同）而卒，太子中（简王）立；《六国年表》楚表与《楚世家》纪年不尽合，故卒年标为推定。", impact: "惠王之世楚的东北界推到淮泗，曾（随）得以存续而为其与国，简王以下楚与齐、鲁、三晋之争成为战国前期东南的主线。", place: "楚都郢（今湖北荆州西北纪南城）", figures: ["楚惠王熊章","楚简王中"], state: "楚国", sources: ["《史记·楚世家》","《史记·六国年表》","《史记·管蔡世家》"], tags: ["楚国","王位","纪年"] }, related: ["cn--b447--p01"] },
  { id: "cn--b431--m01", track: "cn", year: -431, yearApprox: true, dim: "military", weight: 3, title: "楚东向与鲁泗之局", summary: "简王之世楚东压莒、鲁，泗上小国日蹙。", detail: { background: "楚既并陈、蔡、杞，其锋直指沂沭与泗上，莒、鲁、邾之属首当其冲。", process: "莒之亡于楚在《史记》无明文，《竹书纪年》、《战国策》与古说互有异同（或谓为楚所灭，或谓先为齐伐），其年与主谋学界未有定说，故本条作通段推定，不敢指实某役某年。", impact: "莒、鲁之蹙使东方诸国不得不仰齐、晋之援，泗上之争夺由此成为战国初齐、魏与楚三方角力的焦点。", place: "莒、鲁之间（今山东莒县、曲阜一带）", figures: ["楚简王中"], state: "楚国", sources: ["《史记·楚世家》","《史记·鲁周公世家》","《竹书纪年》（古本辑校）"], tags: ["楚国","东向","莒"] }, related: ["cn--b432--p01"] },
  { id: "cn--b430--c01", track: "cn", year: -430, yearApprox: true, dim: "culture", weight: 2, title: "公孟子与墨者之辩", summary: "儒墨相难，辩者之体由是渐具。", detail: { background: "儒以礼乐自名，墨以兼爱相非，两家之辞最易相接，故辩日盛。", process: "《墨子》之《公孟》《耕柱》诸篇记公孟子与子墨子问答之辞，皆称「子墨子」与「公孟子」而不载岁月；其篇之编定在前期抑后学，学者说各不同，故系年全出推定。", impact: "此等问答为先秦论辩之体式所自出：立辞须有「故」、有「理」、有「类」，名家与后期墨家之坚白、同异、方圆之说，皆由此风气而长。", figures: ["墨翟","公孟子"], place: "鲁宋之间（今河南商丘、山东滕州一带）", state: "宋国", sources: ["《墨子·公孟》","《墨子·耕柱》","《墨子·小取》（后期辩者之书，可相印证）"], tags: ["儒墨","论辩","墨学"] }, related: ["cn--b436--c01"] },
  { id: "cn--b429--p01", track: "cn", year: -429, yearApprox: true, dim: "politics", weight: 3, title: "三晋会盟与河内之争", summary: "韩赵魏迭相会结，共争河内、郑宋之地。", detail: { background: "三家分智之后，晋室仅余二邑，三晋对外用兵与相互会盟成为河济、河内诸小国的日常压力。", process: "《史记·六国年表》魏、韩、赵诸表于前430至前420年代屡书「与韩赵会」与「城」某地，《史记·魏世家》《韩世家》《赵世家》所记会、围之事年次多不与表相应，故本条作通段推定。", impact: "三晋的这一同盟期是魏国得以东取河内、西压秦国、北并中山的外交前提，也是前403年册命的实际背景。", place: "晋地河内、河东（今河南西北部、山西西南部）", figures: ["魏文侯","韩取（武子）","赵献侯"], state: "魏国", sources: ["《史记·六国年表》","《史记·魏世家》","《史记·赵世家》"], tags: ["三晋","会盟","河内"] }, related: ["cn--b445--p01"] },
  { id: "cn--b428--f01", track: "cn", year: -428, yearApprox: true, dim: "figure", weight: 3, title: "吴起去鲁入魏", summary: "以兵学见用于魏文侯，从此为魏守西河。", detail: { background: "吴起（卫左成人）学于曾子，事鲁君，因齐人伐鲁、鲁人疑之，杀妻以求将，又为鲁败齐，遂见疑于鲁。", process: "《史记·孙子吴起列传》记其「闻魏文侯贤，欲仕魏」，文侯以问李克（《史记》此名或作李悝），对以「起贪而淫行，然用兵司马穰苴不能过也」，乃以为将而攻秦；其入魏之年无明文，诸家推在前420年代，故标为推定。", impact: "吴起之在魏，使魏有西河之守与河西之郡，其武卒之制与「内修文德、外治武备」之论，为战国兵政之先声。", place: "鲁至魏（今山东曲阜至山西夏县一带）", figures: ["吴起","魏文侯","李克"], state: "魏国", sources: ["《史记·孙子吴起列传》","《汉书·艺文志》（吴起四十八篇）","《吴子》（《武经七书》本，多经后人整订）"], tags: ["吴起","兵家","西河"] }, related: ["cn--b451--m01"] },
  { id: "cn--b427--s01", track: "cn", year: -427, yearApprox: true, dim: "science", weight: 3, title: "度量之校与官立之量", summary: "赋敛、市易赖度量，各国自校其量器。", detail: { background: "春秋末齐氏以大量贷民、小量收之之说已见于《左传》，可见量制与政柄之相关。", process: "《左传》昭公三年晏婴对叔向，历举齐之旧量豆、区、釜、钟与陈氏之新量；战国前期各国自权其轻重，传世与出土之量器（䢰、釜、斗、升之属）多有其铭刻校造之迹，惟其校量制度之起年不可强定，故标为推定。", impact: "度量之校定既是赋税与市易的技术条件，也是国君收回经济权的手段，商鞅「平斗桶权衡丈尺」之令实承此传统。", place: "三晋、齐、鲁", figures: ["晏婴（前事）"], state: "列国", sources: ["《左传·昭公三年》","《史记·商君列传》","《中国科学技术史》（科学出版社中译本）"], tags: ["度量","量器","赋税"] }, related: ["cn--b443--e01"] },
  { id: "cn--b426--p01", track: "cn", year: -426, yearApprox: false, dim: "politics", weight: 4, title: "周室三岁三王", summary: "贞定王崩，哀王、思王、考王迭以杀立。", detail: { background: "周室自敬、元以来微弱，王子争立必倚王叔与执政之党，兄弟相杀于王城之内。", process: "《史记·周本纪》记贞定王崩而长子去疾立是为哀王，哀王兄思王与哀王相攻杀而并立三月，考王又杀思王自立；其在位月数与「三年三王」之解诸家推排互异，今依《六国年表》系其事于此数年之内。", impact: "王室之内难既深，河南桓公之别封遂因之以起，王畿仅存二县；三晋与周之命相不及于外，周之「诸侯」名义自此空存。", figures: ["周贞定王","周哀王","周思王","周考王"], place: "王城与成周（今河南洛阳）", state: "东周王室", sources: ["《史记·周本纪》","《史记·六国年表》","《竹书纪年》（古本辑校）"], tags: ["周室","争立","王畿"] }, related: ["cn--b441--p03"] },
  { id: "cn--b425--d01", track: "cn", year: -425, yearApprox: true, dim: "disaster", weight: 3, title: "河患日亟与堤防之兴", summary: "各国以河为界而筑堤，水患乃移于邻境。", detail: { background: "禹贡之迹既远，战国初河水下游无统一之治，列国各就近筑防以自利。", process: "《史记·河渠书》于河患之叙只举数事，至《汉书·沟洫志》贾让让议乃追论「河从何氏而二海」之说与堤防并起之弊（其文之详略后世有取舍，个别字之释读诸家亦有异说）；战国前期之河防既无系统的史文，本条作通代推定。", impact: "河患与灌溉由此成为国家必须常设的事务，水利与堤防之制自此与战国初之郡县、上计并行而不可分。", place: "黄河下游（今河南北部、河北南部、山东西部）", figures: ["贾让（追论）"], state: "列国", sources: ["《史记·河渠书》","《汉书·沟洫志》","《中国水利史稿》（水利电力出版社）"], tags: ["黄河","堤防","水患"] }, related: ["cn--b465--d01"] },
  { id: "cn--b424--p02", track: "cn", year: -424, yearApprox: true, dim: "politics", weight: 3, title: "秦四世之弱与河西不守", summary: "躁公以下君弱臣强，秦屡为魏所压。", detail: { background: "秦自悼公、躁公以来，公族与诸臣迭相立君，国势不振于东方。", process: "《史记·秦本纪》于躁公、怀公、昭子、灵公之世屡书「与晋战」及「城」某地，《六国年表》秦表与魏表所记战、筑之年多相出入（秦之纪年本有数事与《六国年表》不合，为学界所指出），故本条作通段推定。", impact: "河西不守使秦长期困于关中，其后果是献公、孝公两代以复河西、招贤士为立国之务，商鞅入秦亦起于此。", place: "秦（今甘肃东部、陕西关中）", figures: ["秦躁公","秦灵公"], state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·商君列传》"], tags: ["秦国","河西","中衰"] }, related: ["cn--b451--m01"] },
  { id: "cn--b423--c01", track: "cn", year: -423, yearApprox: true, dim: "culture", weight: 3, title: "儒墨之争的开端", summary: "两家并显，攻难之辞自此相寻。", detail: { background: "墨子非乐、节葬、兼爱诸论，皆就儒家之礼制而发；儒者则斥墨为无父。", process: "《墨子》之《非儒》下篇与《公孟》诸篇记墨、儒往复之语，《孟子·滕文公下》以「能言距杨墨者，圣人之徒也」自任其责，其时皆在战国前期至中期之间，先后之次不可强定，故标为推定。", impact: "这场争论确立了先秦诸子互相批难的问题结构，名家、法家、道家的论辩皆由此而生，是中国思想史上第一次真正的学派之争。", place: "宋、鲁、卫之间", figures: ["墨翟","孟轲（追述）"], state: "列国", sources: ["《墨子·非儒下》","《墨子·公孟》","《孟子·滕文公下》"], tags: ["儒墨","显学","论辩"] }, related: ["cn--b450--c01"] },
  { id: "cn--b422--e01", track: "cn", year: -422, yearApprox: true, dim: "economy", weight: 4, title: "尽地力之教与平籴法", summary: "课勤、均役、平籴，魏以富国。", detail: { background: "战国初地广人众而不尽其力，籴贱伤农、贵伤末，故悝为教民耕与平籴二策。", process: "《汉书·食货志上》记李悝「为魏文侯尽地力之教，食有常平」，治田勤则亩益三斗（《汉书》所纪之数与后世推算者不无异同，故不敢必其数）；《平准书》则以「李克务尽地力」与「白圭乐观时变」并论。", impact: "尽地力与常平之籴是第一个成体系的国家农业与物价政策，为后世之常平仓、劝农桑所自出，也奠定了魏国首强的财政基础。", place: "魏（今山西、河南黄河中游两岸）", figures: ["李悝","魏文侯"], state: "魏国", sources: ["《汉书·食货志上》","《史记·平准书》","《晋书·食货志》"], tags: ["尽地力","平籴","农业政策"] }, related: ["cn--b451--e01", "cn--b422--p01"] },
  { id: "cn--b422--p01", track: "cn", year: -422, yearApprox: true, dim: "politics", weight: 5, title: "魏文侯任李悝变法", summary: "李悝相魏，食有劳而禄有功，魏以大治。", detail: { background: "魏文侯欲强其国而苦于旧世卿之壅，乃用李克（李悝）为相，聚而行之。", process: "《史记·魏世家》《平准书》及《汉书·食货志》于悝相魏、行尽地力之教皆有其文，《说苑·政理》《韩诗外传》复记其治魏之政；《史记》所载魏国诸相之名与李悝之年代自清儒以来疑辨纷出（钱穆《先秦诸子系年》及近世诸说与《纪年》有异），故本条以魏文侯之世为断而标为推定。", impact: "这是战国第一次系统的变法，吴起、商鞅、申不害之业皆沿此而来，中国自此进入以法、以功代世卿的时代。", place: "魏（今山西西南部、河南北部）", figures: ["魏文侯","李悝","翟璜","魏成子"], state: "魏国", sources: ["《史记·魏世家》","《汉书·食货志上》","《说苑·政理》","钱穆《先秦诸子系年》（商务印书馆）"], tags: ["李悝","变法","魏文侯"] }, related: ["cn--b445--p01", "cn--b422--e01", "cn--b421--i01"] },
  { id: "cn--b421--i01", track: "cn", year: -421, yearApprox: true, dim: "institution", weight: 5, title: "李悝造《法经》六篇", summary: "盗、贼、网（囚）、杂、具、捕，王者之制始有成文。", detail: { background: "春秋末晋铸刑鼎、郑铸刑书，刑之公布已有其渐；至悝集诸国刑典而为之经。", process: "《晋书·刑法志》追叙「悝撰次第，造《法经》六篇：一《盗》，二《贼》，三《网》（或作《囚》），四《杂》，五《具》，六《捕》」，又谓商君受之以相秦；《法经》原文不传，其书目与次第只见于后代追记（说家所疑为悝为魏文侯之师或为一人二人之异，说亦不一），故标为推定。", impact: "以法典统辖刑名，从此成为秦汉以下律令体系之祖，中国法制史之为「律之天下」，其端在此。", place: "魏（今山西夏县一带）", figures: ["李悝"], state: "魏国", sources: ["《晋书·刑法志》","《唐律疏议》引《法经》", "《史记·商君列传》","杨宽《战国史》（上海人民出版社）"], tags: ["法经","成文法","法制"] }, related: ["cn--b422--p01", "cn--b437--c01"] },
  { id: "cn--b421--p04", track: "cn", year: -421, yearApprox: true, dim: "politics", weight: 4, title: "西门豹为邺令", summary: "投巫于河以止为河伯娶妇之俗，发民治渠。", detail: { background: "邺在漳水之滨，三老、廷掾与巫祝岁取民女、敛钱，名曰为河伯娶妇，民多亡去。", process: "《史记·滑稽列传》褚少孙所补记西门豹为邺令，因送女之会「复投巫与三老、廷掾、豪长于河」以止其俗，乃发民凿十二渠引漳溉田；《韩非子》《淮南子》所记魏之邺政与《滑稽列传》文义不无出入，其年世尤不可指，故标为推定。", impact: "此事成为后世论吏治、论去巫祝、论水利的三重样板；邺之漳水之利为魏河内要地，亦为曹操以后邺都之基础。", place: "邺（今河北临漳西南、河南安阳北）", figures: ["西门豹","魏文侯"], state: "魏国", sources: ["《史记·滑稽列传》（褚少孙补）","《韩非子·外储说右上》","《汉书·沟洫志》"], tags: ["西门豹","邺","吏治"] }, related: ["cn--b446--i01"] },
  { id: "cn--b420--m01", track: "cn", year: -420, yearApprox: true, dim: "military", weight: 3, title: "武卒之选与复除之赏", summary: "以试科选士，中试者复其户、利其田宅。", detail: { background: "晋之甲士本出国人，战国初兵源日广而须有选练之法与赏功之实。", process: "《荀子·议兵》记魏氏之武卒「以度取之，衣三属之甲，操十二石之弩，负矢五十个，置戈其上，冠鞮带剑，赢三日之粮，日中而趋百里」，中试则「复其户，利其田宅」；吴起为之而「大战三十六，小战七十二（诸书所纪战数不无出入）」，说者谓其制在文侯至武侯之世，其年始不可定，故标为推定。", impact: "以选拔与免赋为激励的募兵制，使魏在战国前期以寡击众而无敌，也是世卿军制向国家常备兵转变中最关键的一步。", place: "魏（今山西、河南黄河中游两岸及河内）", figures: ["吴起","魏文侯"], state: "魏国", sources: ["《荀子·议兵》","《史记·孙子吴起列传》","《汉书·刑法志》"], tags: ["武卒","募兵","军制"] }, related: ["cn--b428--f01"] },
  { id: "cn--b420--s02", track: "cn", year: -420, yearApprox: true, dim: "science", weight: 3, title: "引漳十二渠溉邺", summary: "因水为渠以灌邺田，恶田化为沃野。", detail: { background: "漳水出上党，东北经邺下而溢，土兼碱薄，非引灌不可尽地之利。", process: "《史记·滑稽列传》补文记西门豹「引漳水溉邺」，《汉书·沟洫志》则全录「西门豹为邺长、史起为邺令引漳灌邺」一系之说与邺民歌之之辞（渠之成果在豹抑在史起，两文各有其说，故本条不主一说）。", impact: "此为中国北方有明载之引漳漕溉工程，此后魏之河内、邺中遂为富庶之区；引漳之法并为秦汉以后邺渠、天井渠之张本。", place: "邺（今河北临漳西南）", figures: ["西门豹","史起"], state: "魏国", sources: ["《史记·滑稽列传》（褚少孙补）","《汉书·沟洫志》","《水经注·浊漳水》"], tags: ["水利","漳水","灌溉"] }, related: ["cn--b421--p04"] },
  { id: "cn--b419--m01", track: "cn", year: -419, yearApprox: true, dim: "military", weight: 2, title: "秦堑上郡以距晋魏", summary: "秦退守洛水，城堑上郡，河西尽入于魏。", detail: { background: "魏文侯之世既并西河，秦之河东诸塞日蹙，乃缘洛水而北为堑以自守。", process: "《史记·秦本纪》于是时屡书城、堑之事，谓城堑上郡与重泉；其年次与《六国年表》往往不能相当，秦君自躁公至简公诸家推排差异较大，故系年推定。是时魏数以吴起之众临之，秦人不敢东向。", impact: "自是秦常守洛水，河东之地尽入于魏，魏得以并力东西，而秦之弱直至献公乃复，河西遂为秦魏百年相争之端。", figures: ["秦灵公","吴起"], place: "上郡、重泉（今陕西榆林东南、大荔东南）", state: "秦国", sources: ["《史记·秦本纪》","《史记·魏世家》","《史记·六国年表》"], tags: ["上郡","城堑","河西"] }, related: ["cn--b451--m01"] },
  { id: "cn--b419--p01", track: "cn", year: -419, yearApprox: true, dim: "politics", weight: 3, title: "魏城少梁", summary: "魏逾河筑城少梁，秦人自是不安其西境。", detail: { background: "少梁在龙门之南、黄河西岸，为河西之要口；魏既强，遂连年东取河西之塞。", process: "《史记·六国年表》于前419年前后书晋（魏）「城少梁」，《史记·秦本纪》于灵公之世亦屡书与晋战守之事；两国表、纪所系之年与城地之名，诸家校订颇有出入，故本条年代标为推定。", impact: "少梁既为魏有，秦之河西诸城连为一片，秦不得东出，至献公以后始谋反取；此亦见魏文侯之世以城守进取河西之国策。", place: "少梁（今陕西韩城南）", figures: ["魏文侯","秦灵公"], state: "魏国", sources: ["《史记·六国年表》","《史记·秦本纪》","《史记·魏世家》"], tags: ["河西","少梁","城守"] }, related: ["cn--b451--m01"] },
  { id: "cn--b418--i01", track: "cn", year: -418, yearApprox: true, dim: "institution", weight: 2, title: "上计与玺行之制", summary: "岁会计簿以效于君，符玺印封由是渐密。", detail: { background: "守令之官不出世及，其治状须有可稽，故计簿与玺印之制随县令之制而兴。", process: "三晋之世已有「上计」之语，魏之河东、邺令闻其课；战国印封与「物勒工名」之器足以相发。其制所起之年月无文可指，各方记载差异较大，今约系于五世纪末。", impact: "计簿与玺印使官不再世守其职，君得以朝除而暮夺，战国的任官行政至此有了可考核的手段，为秦汉课计之先声。", figures: ["李悝","韩非"], place: "三晋之地（今山西、河南中部）", state: "魏国", sources: ["《韩非子·内外储说》","《吕氏春秋·知度》","《睡虎地秦墓竹简》（秦律所见计簿之制，年代稍晚而可溯其源）"], tags: ["上计","玺印","任官"] }, related: ["cn--b446--i01"] },
  { id: "cn--b418--m01", track: "cn", year: -418, yearApprox: true, dim: "military", weight: 3, title: "魏、秦河西之役", summary: "魏数西伐秦，秦守封雍之塞以自固。", detail: { background: "魏有安邑、汾水之上，可以顺流而西；秦之都栎阳，正当河西来兵之路。", process: "《史记·秦本纪》记灵公、躁公以来屡「与晋战」，《六国年表》魏、秦两表于诸役之年多不得其会（《秦本纪》之纪年与六国表不合者前人已发其例），故本条作通段推定，不指实某年某地之胜负。", impact: "魏之取河西，使三晋在战国前期握有对秦的绝对主动；秦之「常为雄诸侯」者废，直到献公、孝公之际才扭转过来。", place: "河西、徵（今陕西东部至关中东部）", figures: ["魏文侯","秦灵公"], state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","杨宽《战国史》（上海人民出版社）"], tags: ["秦魏","河西","边战"] }, related: ["cn--b419--p01"] },
  { id: "cn--b417--c01", track: "cn", year: -417, yearApprox: true, dim: "culture", weight: 3, title: "私学与百家之言并兴", summary: "王官之学散为私家之学，著书者自是日众。", detail: { background: "春秋末学在官府之局既坏，战国初士以学术干诸侯，著述遂为进身与传世之具。", process: "《汉书·艺文志》序诸子之流，谓各家「各务为妍」而皆以「应时之须」而作，《史记·孟子荀卿列传》历数齐、魏、赵、楚、周游说论议之士；其分家与著录皆出汉人追整，战国前期之实情不可尽据，故标为推定。", impact: "由是经、子之分与学派之争同时成立，先秦典籍之大部分编纂、传习之关键阶段即在此百年之内。", place: "齐、鲁、三晋、宋、楚", figures: ["墨翟","卜商","杨朱"], state: "列国", sources: ["《汉书·艺文志》","《史记·孟子荀卿列传》","《隋书·经籍志》"], tags: ["私学","诸子","学术"] }, related: ["cn--b450--c01"] },
  { id: "cn--b417--s01", track: "cn", year: -417, yearApprox: true, dim: "science", weight: 2, title: "弓弩之机与远兵", summary: "弩有机括，可以待发中的，远兵始为军要。", detail: { background: "古之兵以弓为远守，射非教习不能中；弩之设机，则众人可以当习战之卒。", process: "《墨子·备高临》有连弩之制的记载，《荀子·议兵》以齐之技击与强弓弩并言；其器之年代与形制不可细求，现存弩机多属战国中以下，攻守诸篇之编定亦有后人所益，故系年推定。", impact: "弩之利于守城与伏发，与墨家诸篇所载守具相须，改变了攻守双方兵力之比，亦使「便弩」成为三晋与齐楚之常备。", figures: ["墨翟","公输班"], place: "宋鲁之间与三晋（今河南、山东、山西交界之地）", state: "宋国", sources: ["《墨子·备高临》","《荀子·议兵》","《吴越春秋·勾践阴谋外传》（晚出而言弩之起）"], tags: ["弩机","兵器","守城"] }, related: ["cn--b452--s01"] },
  { id: "cn--b416--e01", track: "cn", year: -416, yearApprox: true, dim: "economy", weight: 3, title: "兵农相须与田赋之重", summary: "久战须重赋，魏之田赋与武卒之复相为表里。", detail: { background: "战国初用兵无岁无之，兵员与粮赋皆出于田，故田赋与军制不可分为二事。", process: "《汉书·食货志》以李悝「尽地力之教」与常平之籴为魏之富国，《荀子·议兵》以武卒「中试则复其户、利其田宅」为魏之选兵；二者之先后与施行之年史无明文，故系年推定。", impact: "以田赋养兵、以复除劝战，成为战国各国通行之法；此制行之既久，则民之负担与兵员之素质同时下降。", place: "魏之河东、河内", figures: ["李悝"], state: "魏国", sources: ["《汉书·食货志上》","《荀子·议兵》","《史记·平准书》"], tags: ["田赋","武卒","兵农"] }, related: ["cn--b420--m01"] },
  { id: "cn--b416--e02", track: "cn", year: -416, yearApprox: true, dim: "economy", weight: 2, title: "关市之赋与工肆之列", summary: "国恃关市山泽之利，商贾以时转其货。", detail: { background: "城郭既广，市朝之利始为有国者所计校，关市之征与山泽之守并为国用。", process: "《史记·货殖列传》追叙战国之际「与时转移」之贾与以冶铸成业之家，魏之安邑、卫之濮阳、陶皆以市闻；至其税率与关讥之细，各国不同而文不具，各方记载差异较大，故系年推定。", impact: "商业之饶使小国亦足以富，「利归于上」与「工商众则国贫」之议由是分张，为后来重农抑商之言所自起。", figures: ["范蠡","白圭"], place: "卫之濮阳与陶（今河南濮阳、山东定陶）", state: "卫国", sources: ["《史记·货殖列传》","《礼记·王制》","《荀子·富国》"], tags: ["关市","商贾","税赋"] }, related: [] },
  { id: "cn--b415--p01", track: "cn", year: -415, yearApprox: true, dim: "politics", weight: 3, title: "四竞攻秦，秦日削", summary: "河山西丧，诸侯卑秦，秦人以此为耻。", detail: { background: "自厉共公以后秦数易君，大臣庶长得行废置，国中以定君位为务，不能东御晋魏。", process: "秦孝公之诏追叙先君灵公之世「四竞攻秦，秦日削，诸侯卑秦」，谓魏赵韩楚之兵绕边而至此；灵公卒年与「出镇于魏」之解诸家不同，纪年依《秦本纪》与《六国年表》推排不能尽合，故标推定。", impact: "河西之丧为秦人累世之耻，献公、孝公「修穆公之政、复山河之固」与东向之谋，皆以是语自名，遂有商君之事。", figures: ["秦灵公","秦孝公"], place: "秦之雍与河西（今陕西凤翔、韩城一带）", state: "秦国", sources: ["《史记·秦本纪》","《史记·商君列传》","《史记·六国年表》"], tags: ["秦国","河西","求贤"] }, related: ["cn--b419--m01"] },
  { id: "cn--b415--s01", track: "cn", year: -415, yearApprox: true, dim: "science", weight: 3, title: "连弩之机与远兵之具", summary: "墨者所记连弩之车，见战国初机括之用。", detail: { background: "自春秋之弓至战国之弩，机发之远与连发之利渐为兵家所重。", process: "《墨子·备高临》有「连弩之车」之制，《备城门》以下诸篇历言守城器械之具，其机关、望表、绞盘皆有条目；篇中之制出于墨者后学所述，定年之器亦少见可指，故本条系年推定。", impact: "弩机与城防器械之推广，使非贵族的士庶以技术取胜成为可能，是战国军备由车战转为步弩的关键一环。", place: "三晋与宋、鲁之间", figures: ["墨翟（学派）"], state: "列国", sources: ["《墨子·备高临》","《墨子·备城门》（孙诒让《间诂》本）","《司马法》（《武经七书》本）"], tags: ["弩机","器械","军事技术"] }, related: ["cn--b452--s01"] },
  { id: "cn--b414--p01", track: "cn", year: -414, yearApprox: true, dim: "politics", weight: 2, title: "秦简公即位", summary: "君位屡更之后，秦政在庶长而国事有变。", detail: { background: "秦自躁公以后怀、灵迭立，君少臣强，「庶长」与大臣主废立之柄。", process: "简公之立在前414前后，《秦本纪》与《六国年表》于躁、怀、灵、简四君年数互有盈缩，学者推排差异较大，故标推定。其世「初租禾」、「令吏初带剑」之类改制度屡见于表。", impact: "简公一朝秦始有租税与吏制之变，国势虽见卑于诸侯，后来献公之徙栎阳、止从死，实沿此改作之端。", figures: ["秦简公","秦灵公"], place: "秦都雍（今陕西凤翔南）", state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·蒙恬列传》"], tags: ["秦国","君位","庶长"] }, related: ["cn--b415--p01"] },
  { id: "cn--b414--p02", track: "cn", year: -414, yearApprox: true, dim: "politics", weight: 3, title: "中山之复国", summary: "白狄之鲜虞复建国于顾、鄗之间，号中山。", detail: { background: "鲜虞自春秋末屡为晋所伐，其众散而犹聚；晋卿内争之后，狄人复城其地。", process: "《史记·赵世家》与《左传》昭公、定公之间屡见鲜虞、鼓、肥之国名；中山之君有武公之号，其纪年仅赖《史记·六国年表》所载战国旧文与后世转引，赵之纪年与《竹书纪年》异说甚多，故本条系年推定。", impact: "中山既复，赵之北境为其中制，燕赵不得直通，魏于是有假道而伐中山之举，此国存亡成为战国前期河北之主结。", place: "中山（今河北定县、唐县一带）", figures: ["中山武公"], state: "中山国", sources: ["《史记·赵世家》","《史记·六国年表》","《左传·昭公十二年》"], tags: ["中山","白狄","河北"] }, related: ["cn--b476--m01"] },
  { id: "cn--b413--a01", track: "cn", year: -413, yearApprox: true, dim: "art", weight: 2, title: "楚器纹饰之细密", summary: "蟠虺之纹与嵌宝错金，代宗周之旧式。", detail: { background: "战国初年铜器之纹渐去旧式，细如发的蟠虺蚕桑之纹与模印之法并行于江汉淮上。", process: "寿县朱家集与曾侯乙墓所出之器，多错金嵌绿松石之饰，铭文体势亦与春秋不同；此类器之断代有春秋末与战国早期之争，学者所定往往不能一致，故系年推定。", impact: "工巧与新声相须，器不复以明尊卑而或以尚珍异，可见礼乐之器在战国初年已随列国之力而自为风气。", figures: ["曾侯乙","楚王熊章"], place: "楚之寿春与曾之随阳（今安徽寿县、湖北随州）", state: "楚国", sources: ["《寿县朱家集李三孤堆楚王墓》（考古报告）","《曾侯乙墓》（文物出版社考古报告）","《殷周金文集成》（科学出版社）"], tags: ["青铜纹饰","错金","断代"] }, related: ["cn--b433--a01"] },
  { id: "cn--b413--m02", track: "cn", year: -413, yearApprox: true, dim: "military", weight: 3, title: "魏与秦边塞之固", summary: "沿河设戍，河西之守始有常兵。", detail: { background: "魏取河西之后须以常戍守之，此战国边境常备之渐。", process: "《史记·秦本纪》《六国年表》于前410年代屡书秦、魏之城、戍之事，其地望与年次诸家考订不一（王国维以下于魏之西境数城皆有异说），故本条不指一役，作为通段推定。", impact: "常戍与沿边之城使「守土」由采邑之责转为国家之任，吴起所以得为西河守，正以此制度为前提。", place: "魏之西河、上地（今陕西东部黄河两岸）", figures: ["吴起"], state: "魏国", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·孙子吴起列传》"], tags: ["边塞","常戍","西河"] }, related: ["cn--b418--m01"] },
  { id: "cn--b412--i01", track: "cn", year: -412, yearApprox: true, dim: "institution", weight: 3, title: "守、令、丞之官", summary: "县置令长与丞尉，官分而职有守。", detail: { background: "晋之边县有大夫，至战国初改命以守、令，其佐则丞、尉。", process: "战国初之官名多赖后来之玺印、兵器铭刻与秦汉律令以见其略；《史记》诸书所见魏之县令、守，其设置之年史无统纪，故本条系年推定，不敢谓某年立某官。", impact: "令长总政务、丞掌狱赋、尉主盗贼，此三分之制为秦汉县制所本，是战国官僚制最基层、最稳固的一层。", place: "三晋之县邑", figures: ["魏文侯"], state: "魏国", sources: ["《史记·秦本纪》（县、尉之渐）","《史记·魏世家》","《通典·职官》"], tags: ["县制","官制","丞尉"] }, related: ["cn--b464--i01"] },
  { id: "cn--b412--p01", track: "cn", year: -412, yearApprox: true, dim: "politics", weight: 3, title: "越诸咎之乱", summary: "弑君相寻，越国中分裂，楚得以乘其敝。", detail: { background: "句践之后越有吴会之地而内争不已，诸公子各拥其党，夷、越之民不相一。", process: "《史记·越王句践世家》索隐与《楚世家》索隐并引《竹书纪年》，记是时越人弑其君而诸咎亦死于难，又有「越一国三王」之语；其事之年次与古本辑校者所定多不合，故标推定。", impact: "越之内乱使江东不复有霸主，楚得东向而齐之南鄙以安，前四世纪初年东方与淮泗之势由此改观。", figures: ["越王不寿","诸咎"], place: "会稽与琅琊之间（今江苏苏州、山东琅邪一带）", state: "越国", sources: ["《史记·越王句践世家》索隐引《竹书纪年》","《史记·楚世家》索隐引《竹书纪年》","《吴越春秋·勾践阴谋外传》"], tags: ["越国内乱","弑君","纪年"] }, related: ["cn--b472--p01"] },
  { id: "cn--b411--c01", track: "cn", year: -411, yearApprox: true, dim: "culture", weight: 2, title: "墨者之刺丧礼", summary: "非儒之书讥厚葬久丧，见儒者之礼方行。", detail: { background: "儒者以礼乐自名，丧祭之文最为聚讼之端；墨者起而非之，谓其费财而废事。", process: "《墨子》有《非儒》《节葬》诸篇，讥「厚葬久丧」与「蓄私积财」；其篇非出一手，编定有早晚，学者于何篇为墨翟之言、何篇为后学所益，说各不同，故系年推定。", impact: "由墨者之非毁，可见儒者之丧礼已在列国大夫之家盛行，亦开此后孟荀论礼义之端，礼与伪之争遂为百家一题。", figures: ["墨翟","公孟子"], place: "鲁宋之间（今山东、河南交界）", state: "鲁国", sources: ["《墨子·非儒下》","《墨子·节葬下》","《韩非子·显学》"], tags: ["节葬","非儒","丧礼"] }, related: [] },
  { id: "cn--b411--c02", track: "cn", year: -411, yearApprox: true, dim: "culture", weight: 3, title: "兵书之传与删定", summary: "孙、吴、司马之法，战国初已以家次相授。", detail: { background: "《孙子》十三篇行于吴楚，《司马法》出齐，兵家之言至魏而大显。", process: "《史记·孙子吴起列传》称「世俗所称师旅，皆道孙子十三篇、吴起兵法，世多有」；《汉书·艺文志》兵权谋家著录至数十家，谓汉兴张良、韩信序次兵法。其书在战国前期之传习与增删，年月不可考，故系年推定。", impact: "兵学由口传与战例而成书，是中国古代军事思想的第一次定型，吴起之名与《吴子》一书即在此风气中成立。", place: "齐、魏之间", figures: ["孙武（前修）","吴起"], state: "魏国", sources: ["《史记·孙子吴起列传》","《汉书·艺文志》","《银雀山汉墓竹简·孙子兵法》（文物出版社）"], tags: ["兵书","孙子","吴子"] }, related: ["cn--b428--f01"] },
  { id: "cn--b410--e02", track: "cn", year: -410, yearApprox: true, dim: "economy", weight: 3, title: "安邑之会与河东之市", summary: "魏都安邑当盐、路之会，商贾辐辏。", detail: { background: "安邑滨盐池，北通上党，南循河而抵崤函，河东一域自古为货聚之所。", process: "《史记·货殖列传》以「杨、平阳、陈、夏」为西、北贾之枢，其地望皆在河东、河内；《魏都》之制与市令之文战国无征，故本条系年推定，仅言其势。", impact: "都市之利与盐铁之饶，是魏能以一国之赋抗齐、楚、秦三方的财政根据，也是三晋「务本极而致富」之说的现实背景。", place: "安邑与河东（今山西夏县、运城一带）", figures: ["魏文侯"], state: "魏国", sources: ["《史记·货殖列传》","《汉书·地理志下》","《史记·魏世家》"], tags: ["都市","盐池","商业"] }, related: ["cn--b422--e01"] },
  { id: "cn--b410--f01", track: "cn", year: -410, yearApprox: true, dim: "figure", weight: 3, title: "乐羊将魏而谋中山", summary: "文侯以乐羊为将，三年之计始发。", detail: { background: "中山在赵北而魏东，魏欲并之须越赵地千里，乐羊之任在此难中。", process: "《战国策·秦策》《韩非子·说林》及《史记》诸传所记乐羊事，与其伐中山之年互不相齐；近世学者于魏有中山之先后，多据《竹书纪年》与《六国年表》重加推定，说各不同，故本条标为推定。", impact: "乐羊之伐中山是战国前期最远途的攻坚之役，其「乐羊以有功见疑」的结局，成为后世论功与信之关系的常谈。", place: "魏都安邑至中山（今山西夏县至河北定县）", figures: ["乐羊","魏文侯","翟璜"], state: "魏国", sources: ["《战国策·秦策二》","《韩非子·说林上》","《史记·乐毅列传》"], tags: ["乐羊","中山","功疑"] }, related: ["cn--b414--p02"] },
  { id: "cn--b410--f02", track: "cn", year: -410, yearApprox: true, dim: "figure", weight: 3, title: "田子方、段干木之卒世", summary: "文侯师友二人，魏之君臣分义为之增高。", detail: { background: "田子方受业子夏之门人，为魏文侯师；段干木守道不仕，文侯过其闾而式。", process: "《史记·魏世家》《汉书·艺文志》儒家著录《田子方》之属，与《吕氏春秋》《韩诗外传》所记文侯问答诸章，其年次皆无可系；二人卒年尤莫能审，故标为推定。", impact: "师友之名分加上卿禄之实礼，使魏国在战国前期成为士人首选之邦，齐之稷下、秦之客卿皆沿其绪。", place: "魏（今山西西南部）", figures: ["田子方","段干木","魏文侯"], state: "魏国", sources: ["《史记·魏世家》","《史记·仲尼弟子列传》","《吕氏春秋·期贤》"], tags: ["田子方","段干木","礼贤"] }, related: ["cn--b445--f01"] },
  { id: "cn--b410--s01", track: "cn", year: -410, yearApprox: true, dim: "science", weight: 3, title: "古四分历之行用", summary: "以三百六十五度四分之一为岁，十九年七闰。", detail: { background: "春秋之末历数以疏，日食失朔之病已见；更造新历以追合天行，为列国之所同。", process: "后世所据之古四分历以岁实三百六十五日四分之一、朔策二十九日九百四十分日之四百九十九为法，十九岁而七闰齐；其施行于鲁晋齐楚之何时，诸家据《晋书·律历志》《汉书·律历志》所推不同，故系年全出推定。", impact: "章岁之数既定，则播种、蒐狩、朔政皆可预计，历日由此成为国家授时的常制，也是甘石以下天文占候之依据。", figures: ["容成","巫咸","落下闳"], place: "鲁与三晋之司历（今山东、山西一带）", state: "鲁国", sources: ["《汉书·律历志下》","《晋书·律历志上》","《左传·文公元年》（书「闰月」之例）"], tags: ["四分历","章岁","历法"] }, related: ["cn--b444--s01"] },
  { id: "cn--b409--m01", track: "cn", year: -409, yearApprox: true, dim: "military", weight: 5, title: "吴起攻秦取河西五城", summary: "魏师逾河而西，秦之河西诸塞相继不守。", detail: { background: "文侯以吴起为将，乘秦之弱与河西无守，连岁西伐。", process: "《史记·孙子吴起列传》称吴起「为魏将而攻秦，拔五城」（五城之名经传不具），《六国年表》《秦本纪》于秦灵公、出子之世屡书魏之西攻；《传》与表之年有先后不齐者，故本条系年推定。", impact: "五城既拔，魏尽有河西之地而置西河之守，秦退守洛水、泾水之东，此役前后即战国初年秦魏强弱之大转。", place: "河西（今陕西韩城、合阳、大荔一带）", figures: ["吴起","秦灵公"], state: "魏国", sources: ["《史记·孙子吴起列传》","《史记·六国年表》","《史记·秦本纪》"], tags: ["河西","吴起","攻秦"] }, related: ["cn--b451--m01"] },
  { id: "cn--b409--p01", track: "cn", year: -409, yearApprox: true, dim: "politics", weight: 4, title: "赵烈侯任公仲连", summary: "公仲连相赵，进牛畜、荀欣、徐越而修其政。", detail: { background: "赵烈侯籍即位后好音乐，旧臣与新人相持，赵之政未修而国势在东、齐、楚之间。", process: "《史记·赵世家》记烈侯使公仲连相赵，公仲连进牛畜、荀欣、徐越，分别以仁义、举事、节财之用为说，烈侯乃拜三人者谏；其任相与进贤之年《赵世家》不系，故标为推定。", impact: "赵以布衣之士任政，是三晋变法在赵的一支；赵之北边、中牟与后来之「胡服」皆在此一系选贤之制上生长。", place: "赵都中牟、耿（今河南中牟、山西河津一带）", figures: ["赵烈侯籍","公仲连","牛畜","荀欣"], state: "赵国", sources: ["《史记·赵世家》","《史记·六国年表》"], tags: ["赵国","选贤","相权"] }, related: [] },
  { id: "cn--b408--e01", track: "cn", year: -408, yearApprox: true, dim: "economy", weight: 4, title: "秦初租禾", summary: "简公之世秦始缘亩而税，田租之制自此立。", detail: { background: "井田之制既坏，诸侯各以其国之法取于田；魏有「尽地力」之教，秦于此时始变其赋。", process: "《史记·六国年表》秦简公之世书「初租禾」，《秦本纪》于简公之政又书「令吏初带剑」之类；其年自前408、前409二说而推，与《本纪》世次微异，故标为推定。「初租禾」之解，一谓履亩而税始于秦，一谓始定田租之数，两说并存。", impact: "缘亩而税，则田之可占与租之可计并成法制，秦之赋税自是与三晋同流；无此一变，则献公、孝公之世商君「制县邑」「初为赋」诸政无所因。", figures: ["秦简公","商鞅"], place: "秦之关中（今陕西关中平原）", state: "秦国", sources: ["《史记·六国年表》","《史记·秦本纪》","《汉书·食货志上》"], tags: ["初租禾","田租","秦制"] }, related: ["cn--b414--p01", "cn--b594--e01", "cn--b484--i01"] },
  { id: "cn--b408--m02", track: "cn", year: -408, yearApprox: true, dim: "military", weight: 3, title: "乐羊将魏师伐中山", summary: "假道于赵，越代而北，围中山历三年。", detail: { background: "中山阻太行、滹沱之间，去魏国千里而可以制赵之后，文侯欲取之而难其将。", process: "《战国策·秦策二》《韩非子·说林上》与《史记·乐毅列传》所述乐羊之役，皆以三年拔中山为言；其发兵之年据《六国年表》与后世推排定在前408年前后，说有出入，故标为推定。", impact: "此役越国千里而攻城，是战国初最远处之攻坚；魏由是北接邺、赵由是中制，三晋之地南北不续，其局影响赵之战略至百年。", place: "中山（今河北定县、唐县一带）", figures: ["乐羊","魏文侯","中山桓公"], state: "魏国", sources: ["《战国策·秦策二》","《韩非子·说林上》","《史记·乐毅列传》"], tags: ["中山","乐羊","攻坚"] }, related: ["cn--b410--f01"] },
  { id: "cn--b408--p02", track: "cn", year: -408, yearApprox: false, dim: "politics", weight: 3, title: "韩景侯虔改元", summary: "韩氏有专地，其君虔称侯而改元。", detail: { background: "韩自武子、庄子以来与赵、魏共分智氏之地，取其成周之道以南接郑、陈。", process: "《史记·韩世家》与《六国年表》韩表皆以景侯虔之元年在前408年，其前又有「 武子 」「 庄子 」之世次；诸书世次与在位年数小有异同（韩之纪年多赖《纪年》与表的对校），故本年从表而其余推定。", impact: "韩之改元与其后前403年之册命相去五年，韩以荥阳、上党为固而志在郑国，从此郑之亡只是时间问题。", place: "阳翟（今河南禹州）", figures: ["韩景侯虔"], state: "韩国", sources: ["《史记·韩世家》","《史记·六国年表》"], tags: ["韩国","改元","三晋"] }, related: ["cn--b403--p05"] },
  { id: "cn--b407--i01", track: "cn", year: -407, yearApprox: true, dim: "institution", weight: 3, title: "城郭里制与门闾之禁", summary: "里辟胥周，有司守其启闭，民以什伍相司。", detail: { background: "战国之民日益于城，都邑之内里里有司、门有钥、闾有禁，与古之坊里不同。", process: "《墨子·备城门》诸篇所见城之制、门之守与「吏」之任最详，《韩非子》诸篇亦及有司之责成；魏之都邑之制史无明文，其制之定在何时尤不可的，故系年推定。", impact: "城郭里制与县令、上计相配，使国家得计口而役之、按伍而刑之；商鞅之「令民为什伍」与秦汉之里魁、游徼，皆由此等制度而来。", figures: ["魏文侯"], place: "魏之都邑（今山西夏县、河南开封之属）", state: "魏国", sources: ["《墨子·备城门》","《韩非子·内储说上》","《史记·商君列传》"], tags: ["里制","城郭","有司"] }, related: ["cn--b412--i01"] },
  { id: "cn--b406--m03", track: "cn", year: -406, yearApprox: true, dim: "military", weight: 5, title: "魏拔中山", summary: "三年之围始克，魏以其地封太子击。", detail: { background: "乐羊围中山三年而服之，魏须以重臣镇其地，否则越赵之壤不可守。", process: "《战国策》《韩非子》诸篇并记拔中山之功与其后文侯、乐羊之相疑；魏之守中山者为谁、其年在前406抑或前后二年，则各书异辞，故系年推定。", impact: "中山一灭，赵之北境顿蹙；而中山后复国（前380年前后重见），魏之所得不偿其劳，此亦战国初期灭国而不能用其地的显例。", place: "中山（今河北定县一带）", figures: ["乐羊","魏文侯","太子击"], state: "魏国", sources: ["《战国策·秦策二》","《史记·魏世家》","《史记·乐毅列传》"], tags: ["中山","灭国","魏北"] }, related: ["cn--b408--m02"] },
  { id: "cn--b405--f01", track: "cn", year: -405, yearApprox: true, dim: "figure", weight: 3, title: "吴起为西河守", summary: "与士卒同苦乐，秦、韩、楚谓之吴起而不敢近。", detail: { background: "河西新得之土须有能并抚兵民者，吴起以将而守之凡数年。", process: "《史记·孙子吴起列传》记其「与士卒最下者同衣食」，卒有病疽者为吮之，其母哭以「往年公吮其父而父不旋踵死」为言；其与文侯论「在德不在险」一节亦在其守西河之时，年不可定，故标为推定。", impact: "吴起之治西河，把「抚士」与「用法」合为一术，使魏之西鄙安而秦人不得东出，此亦战国将帅兼治军民之始型。", place: "西河（今陕西东部黄河两岸）", figures: ["吴起"], state: "魏国", sources: ["《史记·孙子吴起列传》","《汉书·艺文志》"], tags: ["吴起","西河","抚士"] }, related: ["cn--b409--m01"] },
  { id: "cn--b405--m04", track: "cn", year: -405, yearApprox: true, dim: "military", weight: 5, title: "三晋伐齐入其长城", summary: "鲁宋卫从三晋东行，越长城而阻于海。", detail: { background: "田氏相齐以来未遑外略，三晋既强，遂合东方诸国之兵以入其境。", process: "《史记·田敬仲完世家》记「三晋之君烈侯、文侯、景侯」之师与鲁、宋、卫并力伐齐，《六国年表》于前405年前后书入其长城；诸书所记同异甚多，故本条系年推定。", impact: "三晋以大夫之身破万乘之国，其威已与王侯无异；此事与前403年之册命相为表里，为战国「强国凌小」之始范。", place: "齐之西境长城（今山东平阴至泰安一线）", figures: ["魏文侯","赵烈侯","韩景侯","齐宣公"], state: "齐国", sources: ["《史记·田敬仲完世家》","《史记·六国年表》","《史记·魏世家》"], tags: ["三晋伐齐","长城","齐"] }, related: ["cn--b403--p05"] },
  { id: "cn--b404--x01", track: "cn", year: -404, yearApprox: true, dim: "explore", weight: 3, title: "齐之长城与巨防", summary: "缘泰山之阴连谷为塞，齐之西面始有常险。", detail: { background: "齐有泰山、巨定之阻，而西通三晋、南接鲁宋，其无险处乃以人成之。", process: "《史记·苏秦列传》以「齐西有泰山之城，东有郎邪之阻」为说，齐之缘泰山连谷为塞者，近世考察遗迹犹可寻，惟其初筑之年不可指实，故本条系年推定。", impact: "长城之塞使东方诸国的争衡由野战转为守险；三晋伐齐而越长城一事，正可见此塞之为齐之所恃。", place: "齐西长城（今山东平阴、肥城至青岛一线）", figures: ["齐宣公"], state: "齐国", sources: ["《史记·苏秦列传》","《史记·田敬仲完世家》","杨宽《战国史》（上海人民出版社）"], tags: ["长城","齐","边防"] }, related: ["cn--b405--m04"] },
  { id: "cn--b403--i01", track: "cn", year: -403, yearApprox: false, dim: "institution", weight: 4, title: "名分与纪纲之议", summary: "天子之职莫如礼，礼莫如分，分莫如名。", detail: { background: "册命三家之后，宋、司马光以下皆以名器之假人为亡国之渐立论。", process: "《资治通鉴》卷一于威烈王二十三年下「臣光曰」，谓「天子之职莫如礼，礼莫如分，分莫如名」，以三晋之列于诸侯为纪纲之亡之症；此为后世之论，非当时之文，说之所据则《左传》成公二年「唯器与名不可以假人」。", impact: "此论支配了中国史学对战国开端近千年，今人则以名分之变不过承认既成之实；两种解释的分歧本身即是理解战国的锁钥。", place: "洛阳与后世史论", figures: ["司马光","周威烈王"], state: "东周王室", sources: ["《资治通鉴》卷一","《左传·成公二年》","《史记·周本纪》"], tags: ["名分","礼制","史论"] }, related: ["cn--b403--p05"] },
  { id: "cn--b403--p05", track: "cn", year: -403, yearApprox: false, dim: "politics", weight: 5, title: "周威烈王命三晋为诸侯", summary: "初命晋大夫魏斯、赵籍、韩虔为诸侯。", detail: { background: "三家有晋地而有其众，名分未正则诸侯无以行之于会盟、征伐。", process: "《史记·六国年表》周表「威烈王二十三年，初命晋大夫魏斯、赵籍、韩虔为诸侯」，《周本纪》《晋世家》及《韩》《赵》诸世家并载其事；《资治通鉴》即取此年为其书之首。", impact: "此举以王命追认卿族之有国，战国七雄之局由是成立，故前403年与「三家分晋」同为后世论战国之断限，其最要的意义在名分之自坏。", place: "成周（今河南洛阳）与三晋", figures: ["周威烈王","魏文侯斯","赵烈侯籍","韩景侯虔"], state: "东周王室", sources: ["《史记·六国年表》","《史记·周本纪》","《史记·晋世家》","《资治通鉴》卷一"], tags: ["册命","三家分晋","名分"] }, related: ["cn--b453--p01", "cn--b445--p01"] },
  { id: "cn--b402--a01", track: "cn", year: -402, yearApprox: true, dim: "art", weight: 3, title: "组玉佩与战国前期之服制", summary: "以彩、璜、珩相缀为佩，行与礼相应。", detail: { background: "西周贵族以玉昭其等列，至春秋末、战国初佩玉之制转繁，组数益多。", process: "《周礼·春官·玉人》与《礼记·玉藻》所述佩玉之名与节步之说可考其制；近世战国前期墓葬所出成组之玉，其璜、珩、冲牙之属多经改削而重缀，制度之定年与国属学界尚有异说，故系年推定。", impact: "佩玉之繁正与其礼之松弛同时，玉由「昭等列」转为「饰容貌」，是战国初等级秩序变动的一个可见的指标。", place: "三晋、曾、齐之墓", figures: ["曾侯乙"], state: "列国", sources: ["《周礼·春官·玉人》","《礼记·玉藻》","湖北省博物馆《曾侯乙墓》（文物出版社）"], tags: ["玉佩","服制","礼器"] }, related: ["cn--b433--a01"] },
  { id: "cn--b401--p06", track: "cn", year: -401, yearApprox: true, dim: "politics", weight: 3, title: "周安王立", summary: "威烈王崩，太子骄立，是为安王。", detail: { background: "威烈王在位之时既命三晋，王室之所赖者名分而已。", process: "《史记·周本纪》记威烈王崩而安王骄立，其在位年数与《六国年表》周表推排互有出入（《竹书纪年》所记周世年次亦与《史记》不相应），故系年推定。", impact: "安王之世周与郑、韩相争而借晋之余势，至其崩后周室更无可为；三晋之册命只换得数十年之名义，其效于此尽见。", place: "成周（今河南洛阳）", figures: ["周安王骄","周威烈王"], state: "东周王室", sources: ["《史记·周本纪》","《史记·六国年表》","《竹书纪年》（古本辑校）"], tags: ["东周","王位","纪年"] }, related: ["cn--b403--p05"] },
  { id: "cn--b400--e01", track: "cn", year: -400, yearApprox: true, dim: "economy", weight: 3, title: "宛、郑之铁与南方之冶", summary: "荆豫之间以铁为利，工贾相须而成。", detail: { background: "宛（今南阳）与郑（今新郑）之间山泽之饶，楚越之世已以铜铁名，及战国而工肆益聚。", process: "《史记·货殖列传》「宛与陈、郑」之属皆以铁、以市名于时，《管子·海王》论一郡铁官之利（其篇之年代古今学者说异，或以为出战国齐人之追记），故系年出推定。", impact: "南方之铁与河东之盐、海岱之鱼盐并为当时三大利之区，故「富国」之术不限于耕战，楚、越、三晋之强各有其财赋之根据。", figures: ["郭纵","宛氏之贾"], place: "宛与郑（今河南南阳、新郑）", state: "楚国", sources: ["《史记·货殖列传》","《管子·海王》","《汉书·地理志下》"], tags: ["冶铁","山泽","财赋"] }, related: ["cn--b456--e01"] },
  { id: "cn--b399--d01", track: "cn", year: -399, yearApprox: true, dim: "disaster", weight: 2, title: "军旅之疫与邦国之疠", summary: "大众久聚，疾疫随之；战国前期之灾不可尽考。", detail: { background: "攻战久则大众聚而水食不洁，疠疫随之，虽胜而国病焉。", process: "《史记·天官书》以「天病」「人疠」分而言之，《汉书·五行志》所收战国之灾以日食、地震、大水为多，前期之年月每不可考；《六韬》《吴子》诸书言军中医药，要皆战国以后之所追叙，故本条系年出推定。", impact: "疾疫与饥馑同为战国兵争之大限，故善守国者以「聚大众、先实仓、通水食」为务；其祸至秦、汉之际而史笔始有年可系。", figures: ["吴起"], place: "中原诸国之野（今河南北部、山东西南部）", state: "魏国", sources: ["《史记·天官书》","《汉书·五行志下》","《吕氏春秋·仲冬季》"], tags: ["疾疫","疠","灾荒"] }, related: ["cn--b465--d01"] },
  { id: "cn--b398--p07", track: "cn", year: -398, yearApprox: true, dim: "politics", weight: 3, title: "郑杀其相驷子阳", summary: "郑之权臣以「执齐」之政见杀，郑自此削。", detail: { background: "郑自献公以来屡为韩所陵，其国以小而用重刑，执政与君子相疾。", process: "《吕氏春秋·适威》记子阳之政以令急诛多为失，其民因乱而逐之；《史记·郑世家》于繻公之世别书其贵臣见杀之事，两处所记之年与人事不相应，故系年推定。", impact: "子阳之死与郑之乱，使韩之取郑成为顺势（前375年韩灭郑），而「以苛法守小国」亦成为法家内部自相攻难之例。", place: "郑（今河南新郑）", figures: ["驷子阳","郑繻公"], state: "郑国", sources: ["《吕氏春秋·适威》","《史记·郑世家》","《韩非子·内储说上》"], tags: ["郑国","权臣","苛法"] }, related: [] },
  { id: "cn--b397--m05", track: "cn", year: -397, yearApprox: false, dim: "military", weight: 3, title: "聂政刺韩相侠累", summary: "严遂以千金为寿，聂政直入阶庭刺相。", detail: { background: "濮阳人严仲子（严遂）与韩相侠累有隙，乃以黄金为寿而求士。", process: "《史记·刺客列传》记聂政自齐至，「直入韩阶庭，刺杀侠累，因自皮面决眼、自屠出肠」以全其姊；《战国策·韩策二》所叙与小异，其年据韩之纪年推为前397年，《史记》《战国策》异文之处甚多。", impact: "此事成「士为知己者死」之第二例证（前有豫让），而韩相死于庭，可见战国初卿权之危与游士之锋。", place: "韩都阳翟（今河南禹州）", figures: ["聂政","侠累","严遂","聂荌"], state: "韩国", sources: ["《史记·刺客列传》","《战国策·韩策二》"], tags: ["刺客","聂政","韩"] }, related: ["cn--b453--f01"] },
  { id: "cn--b396--p08", track: "cn", year: -396, yearApprox: true, dim: "politics", weight: 4, title: "魏文侯卒", summary: "在位四十五年终，武侯立而魏之盛未衰。", detail: { background: "文侯以礼贤、任法、守西河、治河内，为一世之盛君。", process: "《史记·魏世家》《六国年表》以文侯之卒在其四十五年（前396），武侯以次年改元；《竹书纪年》所记魏之君年与《史记》多不合，故本条年从《史记》而标推定。", impact: "文侯之世是战国前期唯一的长期稳定期，其死后魏以武侯之猜而失吴起，人才之外流自此始，秦、楚之兴遂有可乘之机。", place: "魏都安邑（今山西夏县西北）", figures: ["魏文侯","魏武侯"], state: "魏国", sources: ["《史记·魏世家》","《史记·六国年表》","《竹书纪年》（古本辑校）"], tags: ["魏文侯","死","魏盛"] }, related: ["cn--b445--p01"] },
  { id: "cn--b395--f02", track: "cn", year: -395, yearApprox: true, dim: "figure", weight: 4, title: "在德不在险", summary: "浮西河而美山河之固，吴起以在德为对。", detail: { background: "武侯乘舟西河，览山河之险而叹魏之宝，坐中未有异议之时。", process: "《史记·孙子吴起列传》载武侯曰「河山带砺，此魏国之宝」，吴起对以「在德不在险」，且举三苗、夏桀、殷纣之恃险而亡为证；此事系于武侯初年，年月无文可定，故标为推定。", impact: "此语为战国君臣论「国之固在民不在地」之典型，其下则武侯终不能容吴起，言与行相反，正见战国前期法治之论与猜功之实之冲突。", place: "西河（今陕西东部黄河两岸）", figures: ["吴起","魏武侯"], state: "魏国", sources: ["《史记·孙子吴起列传》","《吴子》（《武经七书》本）"], tags: ["吴起","在德不在险","君臣"] }, related: ["cn--b405--f01"] },
  { id: "cn--b395--p09", track: "cn", year: -395, yearApprox: true, dim: "politics", weight: 3, title: "魏武侯改元", summary: "击立而元，魏之对外由守而转为进取。", detail: { background: "太子击曾守中山，与田子方、吴起有旧，即位而任公叔之伦为相。", process: "《史记·魏世家》武侯之元年在文侯卒之明年（前395）；魏自是数与秦、楚、齐交兵，亦以中山不复为北患，《纪年》与《表》于此年世多有异说，故标推定。", impact: "武侯之世魏之霸势犹存，而用人之量已出文侯之下，吴起奔楚、商鞅入秦之渐皆伏于此，战国前期之局由魏主转为多国并竞。", place: "魏（今山西西南部、河南北部）", figures: ["魏武侯击","吴起"], state: "魏国", sources: ["《史记·魏世家》","《史记·六国年表》"], tags: ["魏武侯","改元","用人"] }, related: ["cn--b396--p08"] },
  { id: "cn--b394--x01", track: "cn", year: -394, yearApprox: true, dim: "explore", weight: 2, title: "泗上关梁与邾莒之隙", summary: "鲁南诸国接壤，关梁之征与行旅之禁日密。", detail: { background: "鲁、邾、莒、滕、薛错居泗、沂之间，地狭而众，行者须关市之征、津梁之禁。", process: "《史记·鲁周公世家》于三桓之世但书其君之卒立，《汉书·地理志》鲁地条下列其县与山水，《战国策》所记齐魏之争皆由泗上；关梁之目与里数战国不载，故系年出推定。", impact: "小国以关梁自固、以职贡自存，故泗上久为齐、鲁、宋、楚四向之争；「以谋相高」者以通塞为机，而「以地相授」者每及梁、邹、峰、枣之地。", figures: ["鲁恭公","邾隐公"], place: "泗上（今山东邹城、滕州、曲阜之属）", state: "鲁国", sources: ["《史记·鲁周公世家》","《汉书·地理志下》","《战国策·齐策》"], tags: ["泗上","关梁","小国"] }, related: [] },
  { id: "cn--b393--c01", track: "cn", year: -393, yearApprox: true, dim: "culture", weight: 2, title: "道家之言西入于秦", summary: "关尹、老子之学渐布，秦地亦有其传。", detail: { background: "老子为周守藏之史，出关之说乃后世所传；其言「清虚以自守」者自洛入秦。", process: "《史记·老子韩非列传》但言「莫知其所终」，《庄子·天下》以「关尹、老聃乎」相配，《吕氏春秋》贵公、去私诸篇多取此数家之说。其入秦与著录之岁月史无明文，《汉志》道家所载《伊尹》《太公》诸书之真伪亦不可定。", impact: "道家在战国前期本无宗教之名，止于治身与南面之术；《史记》所载周太史儋见秦献公之语，即其入秦之渐，汉初清净理民之治由此溯源。", figures: ["老聃","关尹"], place: "自洛邑至于关中（今河南洛阳至陕西咸阳）", state: "秦国", sources: ["《史记·老子韩非列传》","《庄子·天下》","《汉书·艺文志》道家类"], tags: ["道家","老子","关尹"] }, related: ["cn--b437--c01"] },
  { id: "cn--b392--a01", track: "cn", year: -392, yearApprox: true, dim: "art", weight: 2, title: "错金与镂五之工", summary: "器尚纤巧，错金之工盛行于三晋与齐楚。", detail: { background: "春秋之器尚庄重，及战国而务为纤巧，以错金、嵌宝、细镂为新。", process: "洛阳金村与寿县、辉县诸出土器有错金银、嵌绿松石之属，其断代自春秋末至战国中期聚讼不已，故系年出推定。《考工记》诸齐人之工书，学者多谓出于战国而未必为齐。", impact: "工巧之趋新与礼器之旧用渐不相干，器以珍异相尚，故君子之讥「奇技淫巧」者日众，而「或乱功」之论遂为战国论工者之通义。", figures: ["工垂","离朱"], place: "洛阳与河济之间（今河南洛阳、辉县一带）", state: "周室", sources: ["《周礼·考工记》","《殷周金文集成》（科学出版社）","《考古》《考古学报》所载金村遗物著录"], tags: ["错金","工巧","出土"] }, related: ["cn--b413--a01"] },
  { id: "cn--b391--f03", track: "cn", year: -391, yearApprox: true, dim: "figure", weight: 3, title: "墨子之卒世", summary: "墨翟之终，据其年世推在前四世纪前期。", detail: { background: "墨子及见魏文侯、楚惠王，其游楚、止楚攻宋之事在惠王之末。", process: "《史记·孟子荀卿列传》但言「或曰并孔子时，或曰在其后」，后世据《墨子》所记与年世推排，生年多在前479年至前468年之间，卒年约在前390年代（钱穆、冯友兰诸家所推有异）；本条系年纯出推定。", impact: "墨子之卒与魏文侯、楚惠王之世相及，其后墨分为三而巨子相继，墨家之组织与守城之业由其身后之弟子传之，成为显学之具。", place: "宋、楚、鲁之间", figures: ["墨翟"], state: "宋国", sources: ["《史记·孟子荀卿列传》","钱穆《先秦诸子系年》（商务印书馆）","《墨子·鲁问》"], tags: ["墨子","卒年","显学"] }, related: ["cn--b467--f01"] },
  { id: "cn--b390--s01", track: "cn", year: -390, yearApprox: true, dim: "science", weight: 3, title: "扁鹊治脉与随俗为变", summary: "秦越人之医，过邯郸、入周、至咸阳而各不同科。", detail: { background: "古之医者各守其业，及战国而其技随俗迁移，分科之效始著。", process: "《史记·扁鹊仓公列传》记扁鹊名秦越人，过邯郸闻周人爱子、入周闻秦人敬老人、至秦为小儿医；书中所载赵简子之病与之相及，故其世在六国之际。其年代与《难经》所记多后世之争，故系年推定。", impact: "长桑君之传禁方，脉法与望色自此成家；「信巫不信医」之语又为医与巫分途之论，中国医理之独立，在战国初年已见其端。", figures: ["扁鹊","长桑君"], place: "自邯郸至咸阳（今河北邯郸至陕西咸阳）", state: "赵国", sources: ["《史记·扁鹊仓公列传》","《韩非子·喻老》","《难经》（托名扁鹊，后世所立）"], tags: ["医学","脉法","分科"] }, related: [] },
  { id: "cn--b389--m06", track: "cn", year: -389, yearApprox: true, dim: "military", weight: 3, title: "秦与晋战于武城", summary: "秦惠公西举而东战，魏人复取河西之地。", detail: { background: "秦自献公未立，军政废弛；魏乘其丧与乱，东地之兵数出。", process: "《史记·秦本纪》《六国年表》于秦出子、惠公之世有「与晋战于武城」之文，《秦本纪》所记战不胜与表、诸世家不相应，年次与胜败之归诸家各有取舍，故标为推定。", impact: "是时魏之西兵以河东为根本，秦人不能支；此役与河西之失直接催动了献公以来「止从死、城栎阳、且收河西」之政。", place: "武城（今陕西华县东、华阴一带）", figures: ["秦惠公"], state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·魏世家》"], tags: ["武城","秦魏","河西"] }, related: ["cn--b384--p11"] },
  { id: "cn--b388--m01", track: "cn", year: -388, yearApprox: true, dim: "military", weight: 2, title: "三晋复东向，齐守其西", summary: "魏与赵韩连兵而东，齐人收其泗上之与国。", detail: { background: "三晋自文侯以来数东伐齐，齐之西鄙自廪丘至长城无宁岁。", process: "《史记·田敬仲完世家》《六国年表》于三晋伐齐之役每书「至于长城」与「取某邑」，而其事之年与主名多有阙误；是时齐之与国为卫、鲁、邹、滕，故魏与齐争亦争及泗上，故系年出推定。", impact: "东方之势自是分为两局：齐与泗上诸小国相保，三晋相攻则齐得以乘之；后来田和之求侯，正以此「与诸侯会」为基础。", figures: ["齐康公","魏武侯"], place: "齐西鄙与卫地（今山东北部、河南北部）", state: "齐国", sources: ["《史记·田敬仲完世家》","《史记·六国年表》","《史记·魏世家》"], tags: ["三晋","齐","东向"] }, related: ["cn--b405--m04"] },
  { id: "cn--b387--p01", track: "cn", year: -387, yearApprox: true, dim: "politics", weight: 2, title: "卫适魏，小国之自处", summary: "卫在齐魏之间，亟于自贬以存其社稷。", detail: { background: "卫自悼公以来国小地迫，濮阳帝丘皆为大国之冲，故每役必有所适。", process: "《史记·卫世家》记其君之嗣与徙都，年数绝少可凭；《六国年表》于卫事多阙，故前387年前后卫之所属但可推见，本条系年出推定。", impact: "卫后遂「自贬」称君而服于魏，泗上之邹、鲁、滕、薛亦各以其势为向背，小国之存不在其土地而在其所恃。", figures: ["卫侯","魏武侯"], place: "帝丘、濮阳（今河南濮阳西南）", state: "卫国", sources: ["《史记·卫世家》","《史记·魏世家》","《战国策·卫策》"], tags: ["卫国","附庸","小国"] }, related: [] },
  { id: "cn--b386--p10", track: "cn", year: -386, yearApprox: true, dim: "politics", weight: 5, title: "田和列为诸侯", summary: "周安王命齐太公和为诸侯，田氏有齐。", detail: { background: "田常弑简公以后，田氏尽并国、高二氏之邑；至和而迁康公于海边，分其食邑。", process: "《史记·田敬仲完世家》《周本纪》《六国年表》记周安王二十三年（前379）与前386二说之异：安王之世册命田和，《年表》所系与《世家》之世次不合，迁康公、请列于诸侯之年尤相夺，故标为推定。", impact: "自是齐不再为吕氏之齐而为其新邦，与魏之新诸侯前后相望，战国前期「臣逐君而有国」之路遂为定制，秦、汉以下论禅代之变者每引为据。", place: "齐都临淄（今山东淄博临淄北）", figures: ["齐太公和","齐康公","周安王"], state: "齐国", sources: ["《史记·田敬仲完世家》","《史记·周本纪》","《史记·六国年表》"], tags: ["田氏代齐","册命","齐"] }, related: ["cn--b403--p05"] },
  { id: "cn--b385--p01", track: "cn", year: -385, yearApprox: true, dim: "politics", weight: 5, title: "秦人杀出子，迎献公于魏", summary: "庶长改与国人为变，自魏迎立献公。", detail: { background: "惠公卒而子出立，年少，主大臣之柄者在「庶长」，故内变一起而君嗣绝。", process: "《史记·秦本纪》记出子之世「庶长改与国人袭杀出子，而迎献公于魏」，《六国年表》于出子、献公之年次与《本纪》微异；诸家校订世次长短不一，故系年推定。", impact: "自是秦献公在位二十三年，止从死、徙栎阳、初行为市，秦复起而三晋不暇西顾，中国之形势由此一转。", figures: ["秦献公","秦出子","庶长改"], place: "秦都雍至栎阳（今陕西凤翔至临潼）", state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·封禅书》"], tags: ["秦国","废立","内变"] }, related: ["cn--b415--p01"] },
  { id: "cn--b384--i01", track: "cn", year: -384, yearApprox: false, dim: "institution", weight: 5, title: "秦止从死", summary: "献公元年止人殉，关中之俗自此一变。", detail: { background: "秦之先公以人从死，见于《左传》《诗经·黄鸟》之刺，其旧俗至战国初犹在。", process: "《史记·秦本纪》「（献公）元年，止从死」，《秦始皇本纪》后附之《系》叙述秦之世次与葬仪亦及此；其年据《年表》推排在前384年（诸家校订有前385、前384两说），故年标推定。", impact: "止从死既保全国之人力，也斩断了西周以来以人奉死的礼俗，是秦国由「戎俗之国」转为「民事为国本」之关键一步。", place: "秦（今陕西关中）", figures: ["秦献公"], state: "秦国", sources: ["《史记·秦本纪》","《诗经·秦风·黄鸟》","《左传·文公六年》"], tags: ["人殉","献公","礼俗之变"] }, related: ["cn--b384--p11"] },
  { id: "cn--b384--p11", track: "cn", year: -384, yearApprox: false, dim: "politics", weight: 4, title: "秦献公入而立", summary: "自魏还国，止从死，秦之本始改于一世。", detail: { background: "秦自躁公以来君弱臣强、数易嗣，献公（师隰）少在魏，至是以国人迎之而还。", process: "《史记·秦本纪》记出公之世秦人自魏迎献公立之（其年自前385至前384，两说由《秦本纪》与《六国年表》之异而来），《索引》、诸家于其改元之年各有所定，故本条从其大较而年标推定。", impact: "献公之立是秦复强之始，止从死、城栎阳、户籍伍比诸政由是相次，孝公之求贤令、商鞅之入秦皆在此一转向之后。", place: "秦都（今陕西凤翔至栎阳一带）", figures: ["秦献公师隰","秦出子"], state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·商君列传》"], tags: ["秦献公","即位","转折"] }, related: ["cn--b384--i01"] },
  { id: "cn--b383--m01", track: "cn", year: -383, yearApprox: false, dim: "military", weight: 3, title: "赵与中山战于房子", summary: "中山复振，东向争赵之房子。", detail: { background: "魏既拔中山而封其公子，未几年中山自复其国，负其众以陵赵。", process: "《史记·赵世家》记敬侯四年与中山战于房子；中山复国之年在《战国策》与《六国年表》所据史料皆不具，学者或主前四世纪之初中叶，或谓中山之「武公」与「桓公」之异（近世学者多据魏文侯以后中山之器与铭文推之，异说至今未定），故中山复国之年标为推定，房子之役则年次可信。", impact: "自此中山数与赵战，「国境方千里」而能「拒燕赵」，成为三晋北边之大患，赵必并中山而后北事得专。", figures: ["赵敬侯","中山国君"], place: "房子（今河北赞皇东北）", state: "赵国", sources: ["《史记·赵世家》","《史记·六国年表》","《战国策·中山策》"], tags: ["中山","房子","赵边"] }, related: ["cn--b406--m03"] },
  { id: "cn--b382--p13", track: "cn", year: -382, yearApprox: true, dim: "politics", weight: 5, title: "吴起相楚变法", summary: "明法审令，捐不急之官，废公族疏远者。", detail: { background: "吴起见逐于魏，楚悼王素闻其贤，至则以为相而属以国政。", process: "《史记·孙子吴起列传》「至则相楚，明法审令，捐不急之官，废公族疏远者，以抚养战斗之士，要在强兵，破驰说之言从横者」，《韩非子·和氏》则以大臣太贵、私有徒众为楚病；其相楚之年在悼王末年以前，诸家推排在前386至前382之间，故本条标为推定。", impact: "楚之变法行于最顽固的世族之邦，「贵人实多，贱人不敢议其上」之俗一时为挫；楚之南收扬越、北并陈蔡由此而强，然其业系于一人、于一君，故不能如秦久之。", place: "楚都郢（今湖北荆州西北纪南城）", figures: ["吴起","楚悼王"], state: "楚国", sources: ["《史记·孙子吴起列传》","《韩非子·和氏》","《史记·楚世家》"], tags: ["吴起","变法","楚国"] }, related: ["cn--b395--f02", "cn--b421--i01"] },
  { id: "cn--b381--c01", track: "cn", year: -381, yearApprox: true, dim: "culture", weight: 4, title: "墨者孟胜死阳城君之难", summary: "师死而守其器，从死者三十八人（诸书不同）。", detail: { background: "墨者以钜子为师，相属以行义；阳城君为楚之封君而学于墨者孟胜，以国属之而约车为符。", process: "《吕氏春秋·上德》记阳城君死难而楚收其国，孟胜以「与人之兄居而杀其弟、与人之父处而贼其子」不自免，遣二大师致钜子于田襄子而后死，从死者数十人；《淮南子·泰族》亦及其赴汤火之义。死事之年据楚悼王卒而推，从死人数诸书不齐，故标为推定。", impact: "布衣之徒能以其组织从师于死，是先秦学派之为「团体」最烈的一案；墨者之严如此，其后遂中分为三，而侠以武犯禁者亦以其义自名。", figures: ["孟胜","阳城君","田襄子"], place: "楚之阳城（今河南信阳、湖北应山一带）", state: "楚国", sources: ["《吕氏春秋·上德》","《淮南子·泰族训》","《韩非子·显学》"], tags: ["墨者","钜子","死义"] }, related: ["cn--b450--c01"] },
  { id: "cn--b381--p14", track: "cn", year: -381, yearApprox: false, dim: "politics", weight: 4, title: "楚悼王卒，宗室攻吴起", summary: "起伏尸以当宗室之兵，坐射起者夷宗以百数。", detail: { background: "吴起之变法，「封君之子孙三世而收爵禄」，楚之贵戚怨望已积。", process: "《史记·孙子吴起列传》记悼王卒而宗室大臣作乱、攻吴起，起奔伏于王之尸，攻者横弩射起并中王尸；既葬而太子即位，坐射起与中王尸者夷宗死者以百数（诸书所记家数不同，未可强齐）。", impact: "楚之变法与悼王之身俱终，其后楚虽强而不能用法，吴起、商鞅同功而异效，成为论战国变法最锋利的对照。", place: "楚都郢（今湖北荆州西北纪南城）", figures: ["楚悼王","吴起","楚肃王"], state: "楚国", sources: ["《史记·孙子吴起列传》","《史记·楚世家》","《韩非子·和氏》"], tags: ["吴起","楚变法","宗室"] }, related: ["cn--b382--p13"] },
  { id: "cn--b380--i03", track: "cn", year: -380, yearApprox: true, dim: "institution", weight: 4, title: "改法为律之渐", summary: "《法经》由三晋入秦，法之为律自此而名。", detail: { background: "李悝之法既行于魏，其书随士人之西入而传于秦。", process: "《晋书·刑法志》谓李悝之《法经》，商君受之以相秦，改法为律；《唐律疏议》序论同有其说。其传之之年与「律」名之所起，古无明文，说家推定在前390至前360年间，故本条系年推定。", impact: "自是「律」为国家正刑之名，汉承秦制、唐因隋文，中国法律之文体以律为主干，其源出于战国魏之《法经》，本分片所记至此而见其一端。", place: "魏与秦之间（今山西、陕西黄河两岸）", figures: ["李悝","商鞅（后事）"], state: "魏国", sources: ["《晋书·刑法志》","《唐律疏议》序","杨宽《战国史》（上海人民出版社）"], tags: ["法经","律","法制"] }, related: ["cn--b421--i01"] },
];
